// Modo Verdadeiro/Falso: alternativa mais rápida, bom pra revisar conceitos.
export const TRUE_FALSE = [
  { id: 'tf-trindade', statement: 'A Trindade significa que existem três Deuses.', statementEn: 'The Trinity means there are three Gods.', answer: false, explanation: 'A Trindade é UM Deus em três pessoas (Pai, Filho, Espírito Santo). Triteísmo é heresia.', explanationEn: 'The Trinity is ONE God in three persons (Father, Son, Holy Spirit). Tritheism is heresy.' },
  { id: 'tf-canon-prot', statement: 'A Bíblia protestante e a católica têm o mesmo número de livros.', statementEn: 'The Protestant and Catholic Bibles have the same number of books.', answer: false, explanation: 'A católica tem 73 livros, a protestante 66. A diferença são 7 livros do Antigo Testamento (Tobias, Judite, 1 e 2 Macabeus, Sabedoria, Eclesiástico e Baruc), além de partes de Ester e Daniel.', explanationEn: 'The Catholic has 73 books, the Protestant 66. The difference is 7 Old Testament books (Tobit, Judith, 1 and 2 Maccabees, Wisdom, Sirach and Baruch), plus parts of Esther and Daniel.' },
  { id: 'tf-eucaristia', statement: 'Na Eucaristia, o pão e o vinho se tornam verdadeiramente Corpo e Sangue de Cristo.', statementEn: 'In the Eucharist, the bread and wine truly become the Body and Blood of Christ.', answer: true, explanation: 'É a doutrina da presença real, ensinada desde os Padres da Igreja (Inácio de Antioquia, Justino). O termo transubstanciação surge no séc. XII, é usado pelo IV Concílio de Latrão (1215) e foi definido pelo Concílio de Trento (1551).', explanationEn: 'This is the doctrine of the Real Presence, taught since the Church Fathers (Ignatius of Antioch, Justin). The term transubstantiation arose in the 12th century, was used by the Fourth Lateran Council (1215) and was defined by the Council of Trent (1551).' },
  { id: 'tf-papa-impec', statement: 'A infalibilidade papal significa que o Papa não pode pecar.', statementEn: 'Papal infallibility means the Pope cannot sin.', answer: false, explanation: 'Não. Significa que ele não pode errar quando define solenemente uma doutrina de fé ou moral. Papas pecam como qualquer um.', explanationEn: 'No. It means he cannot err when solemnly defining a doctrine of faith or morals. Popes sin like anyone else.' },
  { id: 'tf-maria-deusa', statement: 'Católicos consideram Maria uma deusa.', statementEn: 'Catholics consider Mary a goddess.', answer: false, explanation: 'Maria é venerada, não adorada. A adoração (latria) se dá só a Deus, a veneração especial (hiperdulia) a Maria e a veneração comum (dulia) aos santos.', explanationEn: 'Mary is venerated, not worshipped. Worship (latria) is given to God alone, special veneration (hyperdulia) to Mary and common veneration (dulia) to the saints.' },
  { id: 'tf-confissao-bib', statement: 'A confissão a um padre está na Bíblia.', statementEn: 'Confession to a priest is in the Bible.', answer: true, explanation: 'João 20,21-23: Jesus dá aos apóstolos o poder de perdoar ou reter pecados. Tiago 5,16 manda confessar uns aos outros.', explanationEn: 'John 20:21-23: Jesus gives the apostles the power to forgive or retain sins. James 5:16 commands confessing to one another.' },
  { id: 'tf-purgatorio', statement: 'O Purgatório é uma "segunda chance" após a morte para quem não se salvou.', statementEn: 'Purgatory is a "second chance" after death for those who weren\'t saved.', answer: false, explanation: 'Não. O Purgatório é purificação de quem JÁ se salvou, mas ainda tem apegos a corrigir antes de entrar no Céu.', explanationEn: 'No. Purgatory is purification of those who are ALREADY saved, but still have attachments to correct before entering Heaven.' },
  { id: 'tf-jesus-disse-cat', statement: 'Jesus disse expressamente: "Eu fundo a Igreja Católica".', statementEn: 'Jesus expressly said: "I found the Catholic Church".', answer: false, explanation: 'Não com essas palavras. Ele disse: "tu és Pedro, e sobre esta pedra edificarei a minha Igreja" (Mt 16,18). "Católica" quer dizer universal, e o termo aplicado à Igreja aparece já em Inácio de Antioquia, por volta de 110.', explanationEn: 'Not in those words. He said: "thou art Peter; and upon this rock I will build my church" (Mt 16:18). "Catholic" means universal, and the term applied to the Church appears as early as Ignatius of Antioch, around 110.' },
  { id: 'tf-galileu-tortura', statement: 'Galileu foi torturado pela Inquisição.', statementEn: 'Galileo was tortured by the Inquisition.', answer: false, explanation: 'Não há prova de que tenha sido torturado: no interrogatório de 1633 houve, no máximo, a ameaça formal prevista no processo. Ele se retratou, foi condenado à prisão domiciliar e, em sua casa de Arcetri, terminou os Discursos sobre duas novas ciências (1638).', explanationEn: 'There is no evidence he was tortured: in the 1633 interrogation there was at most the formal threat provided for by the procedure. He recanted, was sentenced to house arrest and, at his home in Arcetri, completed the Two New Sciences (1638).' },
  { id: 'tf-bigbang-padre', statement: 'A teoria do Big Bang foi proposta por um sacerdote católico.', statementEn: 'The Big Bang theory was proposed by a Catholic priest.', answer: true, explanation: 'Georges Lemaître, sacerdote belga, em 1927. Inicialmente Einstein resistiu, mas depois aceitou.', explanationEn: 'Georges Lemaître, Belgian priest, in 1927. Einstein initially resisted, but later accepted.' },
  { id: 'tf-sola-fide-biblia', statement: 'A expressão "sola fide" (só pela fé) aparece literalmente na Bíblia defendendo a justificação.', statementEn: 'The phrase "sola fide" (by faith alone) appears literally in the Bible defending justification.', answer: false, explanation: 'Tiago 2,24 é o único versículo com a expressão "somente pela fé" (em grego, ek písteos mónon), e no sentido oposto: "o homem é justificado pelas obras e não somente pela fé". A expressão está na Bíblia, mas para negar a doutrina de Lutero.', explanationEn: 'James 2:24 is the only verse with the phrase "by faith only" (Greek ek pisteos monon), and in the opposite sense: "by works a man is justified, and not by faith only". The phrase is in the Bible, but in order to deny Luther\'s doctrine.' },
  { id: 'tf-purgatorio-macabeus', statement: 'O Purgatório tem base no Antigo Testamento, em 2 Macabeus.', statementEn: 'Purgatory has a basis in the Old Testament, in 2 Maccabees.', answer: true, explanation: '2 Macabeus 12,43-46: Judas Macabeu manda oferecer um sacrifício pelos soldados mortos, "para que os mortos fossem livres de suas faltas". O Catecismo (§1032) apoia nesse texto a oração pelos defuntos e a purificação depois da morte.', explanationEn: '2 Maccabees 12:43-46: Judas Maccabeus has a sacrifice offered for the fallen soldiers, "that they may be loosed from sins". The Catechism (§1032) bases on this text the prayer for the dead and purification after death.' },
  { id: 'tf-papa-sempre-infalivel', statement: 'O Papa é infalível em todas as suas declarações públicas.', statementEn: 'The Pope is infallible in all his public statements.', answer: false, explanation: 'Só quando fala ex cathedra, definindo solenemente uma doutrina de fé ou moral para toda a Igreja. Isso aconteceu poucas vezes, como na Imaculada Conceição (1854) e na Assunção (1950).', explanationEn: 'Only when he speaks ex cathedra, solemnly defining a doctrine of faith or morals for the whole Church. This has happened only a few times, as with the Immaculate Conception (1854) and the Assumption (1950).' },
  { id: 'tf-jesus-25dez', statement: 'A Bíblia afirma que Jesus nasceu no dia 25 de dezembro.', statementEn: 'The Bible states that Jesus was born on December 25th.', answer: false, explanation: 'A Bíblia não menciona a data do nascimento. O 25 de dezembro foi fixado no séc. IV. Há hipóteses sobre a data real (setembro-outubro ou dezembro), mas nenhuma certeza.', explanationEn: 'The Bible does not mention the birth date. December 25 was fixed in the 4th century. There are hypotheses about the real date (September-October or December), but no certainty.' },
  { id: 'tf-bigbang-nome-hoyle', statement: 'O nome "Big Bang" foi criado pelo padre Lemaître para descrever sua teoria.', statementEn: 'The name "Big Bang" was coined by Father Lemaître to describe his theory.', answer: false, explanation: 'O nome surgiu em 1949, num programa de rádio da BBC, na boca do físico Fred Hoyle, que defendia a teoria rival do estado estacionário (ele negou depois que fosse zombaria). Lemaître chamava sua ideia de "hipótese do átomo primordial".', explanationEn: 'The name arose in 1949, on a BBC radio program, from physicist Fred Hoyle, who defended the rival steady-state theory (he later denied it was meant as mockery). Lemaître called his idea the "hypothesis of the primeval atom".' },
  { id: 'tf-confissao-anual', statement: 'A Igreja Católica obriga os fiéis a se confessarem pelo menos uma vez por ano.', statementEn: 'The Catholic Church obliges the faithful to go to confession at least once a year.', answer: true, explanation: 'É um dos preceitos da Igreja: confessar fielmente os pecados graves pelo menos uma vez por ano (Código de Direito Canônico, cân. 989). O Catecismo (§2042) diz que isso assegura a preparação para a Eucaristia.', explanationEn: 'It is one of the precepts of the Church: to confess one\'s grave sins faithfully at least once a year (Code of Canon Law, can. 989). The Catechism (§2042) says this ensures preparation for the Eucharist.' },
  { id: 'tf-irmaos-jesus-biologicos', statement: 'A Bíblia prova definitivamente que Jesus teve irmãos biológicos de Maria.', statementEn: 'The Bible definitively proves that Jesus had biological brothers from Mary.', answer: false, explanation: 'O grego adelphós e o hebraico ah ("irmão") podiam indicar primos e outros parentes. Marcos 15,40 mostra que Tiago e José, chamados "irmãos" de Jesus (Mc 6,3), eram filhos de outra Maria. E Hegésipo (séc. II, citado por Eusébio) chama Simeão, filho de Clopas, irmão de José, de primo do Senhor.', explanationEn: 'The Greek adelphos and the Hebrew ah ("brother") could designate cousins and other relatives. Mark 15:40 shows that James and Joseph, called Jesus\'s "brothers" (Mk 6:3), were sons of another Mary. And Hegesippus (2nd century, quoted by Eusebius) calls Simeon, son of Clopas, Joseph\'s brother, a cousin of the Lord.' },
  { id: 'tf-testamento-alianca', statement: 'A palavra "testamento" em "Novo Testamento" traduz o grego para "aliança".', statementEn: 'The word "testament" in "New Testament" translates the Greek word for "covenant".', answer: true, explanation: '"Testamento" vem do latim testamentum, que traduz o grego diathéke (aliança), que por sua vez traduz o hebraico berit. Na Última Ceia Jesus diz: "Este cálice é a Nova Aliança em meu sangue" (Lc 22,20).', explanationEn: '"Testament" comes from the Latin testamentum, which renders the Greek diatheke (covenant), itself a rendering of the Hebrew berith. At the Last Supper Jesus says: "This is the chalice, the new testament in my blood" (Lk 22:20).' },
  { id: 'tf-missa-justino', statement: 'A estrutura básica da Missa (Liturgia da Palavra + Eucaristia) já aparece no séc. II.', statementEn: 'The basic structure of the Mass (Liturgy of the Word + Eucharist) already appears in the 2nd century.', answer: true, explanation: 'São Justino, na I Apologia (cap. 65-67, por volta de 155), descreve a assembleia de domingo: leitura das "memórias dos apóstolos" e dos profetas, homilia, preces, apresentação do pão e do vinho, oração de ação de graças e comunhão. É a mesma estrutura da Missa atual.', explanationEn: 'St. Justin, in his First Apology (ch. 65-67, around 155), describes the Sunday assembly: reading of the "memoirs of the apostles" and the prophets, homily, prayers, presentation of bread and wine, thanksgiving prayer and communion. It is the same structure as today\'s Mass.' },
  { id: 'tf-celibato-medieval', statement: 'O celibato sacerdotal é uma imposição medieval sem nenhuma raiz apostólica.', statementEn: 'Priestly celibacy is a medieval imposition with no apostolic roots.', answer: false, explanation: 'Jesus fala dos que renunciam ao casamento "por amor do Reino dos Céus" (Mt 19,12), e Paulo elogia o celibato por permitir dedicar-se inteiramente ao Senhor (1 Cor 7,32-35). O Concílio de Elvira (por volta de 306) já exigia continência dos clérigos, e a lei do celibato se consolidou no Ocidente com os concílios de Latrão I e II (1123 e 1139).', explanationEn: 'Jesus speaks of those who renounce marriage "for the kingdom of heaven" (Mt 19:12), and Paul praises celibacy because it allows one to be wholly devoted to the Lord (1 Cor 7:32-35). The Council of Elvira (around 306) already required continence of clerics, and the law of celibacy was consolidated in the West with the First and Second Lateran Councils (1123 and 1139).' },
  { id: 'tf-criacao-6dias', statement: 'A Igreja Católica ensina que o mundo foi criado em seis dias literais de 24 horas.', statementEn: 'The Catholic Church teaches that the world was created in six literal 24-hour days.', answer: false, explanation: 'A Igreja não impõe uma leitura literal dos seis dias. Santo Agostinho, no início do séc. V (Sobre o Gênesis ao pé da letra), já entendia os "dias" de modo não cronológico, e a Pontifícia Comissão Bíblica (1909) admitiu ler "dia" como um período de tempo. O que a fé ensina é que Deus criou tudo do nada, não a duração.', explanationEn: 'The Church does not impose a literal reading of the six days. St. Augustine, in the early 5th century (The Literal Meaning of Genesis), already understood the "days" in a non-chronological way, and the Pontifical Biblical Commission (1909) allowed "day" to be read as a period of time. What faith teaches is that God created everything from nothing, not the duration.' },
  { id: 'tf-beatificacao-canonizacao', statement: 'Beatificação e canonização são a mesma coisa com nomes diferentes.', statementEn: 'Beatification and canonization are the same thing with different names.', answer: false, explanation: 'A beatificação permite culto local ou regional e exige um milagre, salvo no caso dos mártires. A canonização estende o culto à Igreja inteira, exige em regra mais um milagre e é tida como definitiva (a maioria dos teólogos a considera infalível).', explanationEn: 'Beatification permits local or regional veneration and requires one miracle, except for martyrs. Canonization extends veneration to the whole Church, as a rule requires one more miracle, and is held to be definitive (most theologians consider it infallible).' },
  { id: 'tf-apologetica-violencia', statement: 'Apologética cristã justifica o uso de violência para defender a fé.', statementEn: 'Christian apologetics justifies the use of violence to defend the faith.', answer: false, explanation: '1 Pedro 3,15, o versículo que dá nome à apologética, pede que se dê a razão da esperança "com suavidade e respeito". Apologética é defesa com argumentos, nunca coerção.', explanationEn: '1 Peter 3:15-16, the passage that gives apologetics its name, asks that the reason for our hope be given "with modesty and fear". Apologetics is defense by argument, never coercion.' },
  { id: 'tf-evolucao-alma', statement: 'Aceitar a teoria da evolução biológica é incompatível com a fé católica.', statementEn: 'Accepting the theory of biological evolution is incompatible with Catholic faith.', answer: false, explanation: 'Pio XII (Humani Generis, 1950) admitiu o estudo da origem do corpo humano por evolução, mantendo que as almas são criadas diretamente por Deus, e João Paulo II (1996) disse que a evolução é "mais que uma hipótese". A evolução teísta é uma posição admitida.', explanationEn: 'Pius XII (Humani Generis, 1950) allowed the study of the origin of the human body through evolution, holding that souls are created directly by God, and John Paul II (1996) said that evolution is "more than a hypothesis". Theistic evolution is an accepted position.' },
  { id: 'tf-niceia-canon', statement: 'O Concílio de Niceia (325) escolheu quais livros entrariam na Bíblia.', statementEn: 'The Council of Nicaea (325) chose which books would be included in the Bible.', answer: false, explanation: 'Niceia tratou da divindade de Cristo (arianismo), da data da Páscoa e de questões de disciplina, e nenhum dos seus cânones fala da lista dos livros. Listas completas aparecem com Santo Atanásio (367) e nos sínodos de Hipona (393) e Cartago (397).', explanationEn: 'Nicaea dealt with Christ\'s divinity (Arianism), the date of Easter and matters of discipline, and none of its canons speaks of the list of books. Complete lists appear with St. Athanasius (367) and at the synods of Hippo (393) and Carthage (397).' },
  { id: 'tf-pecado-mortal-graca', statement: 'Todo pecado mortal priva o cristão da graça santificante e da amizade com Deus.', statementEn: 'Every mortal sin deprives the Christian of sanctifying grace and friendship with God.', answer: true, explanation: 'O pecado mortal destrói a caridade e priva da graça santificante (Catecismo §1855 e §1861). Exige três condições: matéria grave, plena consciência e consentimento deliberado (§1857). A Confissão restitui a graça perdida.', explanationEn: 'Mortal sin destroys charity and deprives one of sanctifying grace (Catechism §1855 and §1861). It requires three conditions: grave matter, full knowledge and deliberate consent (§1857). Confession restores the lost grace.' },
  { id: 'tf-tj-poste', statement: 'As Testemunhas de Jeová afirmam que Jesus morreu num poste, não numa cruz.', statementEn: 'Jehovah\'s Witnesses claim Jesus died on a stake, not a cross.', answer: true, explanation: 'Elas traduzem o grego staurós como "estaca de tortura". Mas, no uso romano, a palavra cobria a cruz com trave, e as fontes antigas falam do condenado carregando a trave transversal (patibulum). Tomé fala das marcas dos pregos nas mãos, no plural (Jo 20,25), o que combina com braços abertos, e autores do séc. II, como Justino, já descrevem a cruz com trave.', explanationEn: 'They translate the Greek stauros as "torture stake". But in Roman usage the word covered a cross with a crossbeam, and ancient sources speak of the condemned man carrying the crossbeam (patibulum). Thomas speaks of the print of the nails in his hands, in the plural (Jn 20:25), which fits outstretched arms, and 2nd-century authors such as Justin already describe the cross with a crossbeam.' },
  { id: 'tf-relativismo-bib', statement: 'A Bíblia apresenta um padrão de moralidade que muda completamente de acordo com a cultura e o tempo.', statementEn: 'The Bible presents a standard of morality that changes completely according to culture and time.', answer: false, explanation: 'O Decálogo (Ex 20), as Bem-Aventuranças (Mt 5) e a lei natural inscrita no coração (Rm 2,14-15) apontam para uma ética objetiva. A aplicação muda em casos concretos, o princípio não.', explanationEn: 'The Decalogue (Ex 20), the Beatitudes (Mt 5), and the natural law written in the heart (Rm 2:14-15) point to an objective ethics. The application changes in specific cases, the principle does not.' },
  { id: 'tf-resurreicao-corpo', statement: 'A fé cristã afirma a ressurreição do corpo, não apenas a imortalidade da alma.', statementEn: 'The Christian faith affirms the resurrection of the body, not just the immortality of the soul.', answer: true, explanation: 'O Credo afirma "a ressurreição da carne". Paulo, em 1 Coríntios 15, fala de um corpo ressuscitado glorioso, e Jesus ressuscitou com o corpo: o túmulo estava vazio. Isso difere do platonismo, que esperava só a imortalidade da alma.', explanationEn: 'The Creed affirms "the resurrection of the body". Paul, in 1 Corinthians 15, speaks of a glorious risen body, and Jesus rose bodily: the tomb was empty. This differs from Platonism, which hoped only for the immortality of the soul.' },
  { id: 'tf-maria-perpetua-virg', statement: 'A virgindade perpétua de Maria é ensinada pela Igreja Católica como doutrina.', statementEn: 'The perpetual virginity of Mary is taught by the Catholic Church as doctrine.', answer: true, explanation: 'A Igreja professa Maria "sempre virgem", antes, durante e depois do parto de Jesus (Catecismo §499-501). O título aparece no II Concílio de Constantinopla (553), e o Sínodo de Latrão (649) o declarou expressamente. Os "irmãos de Jesus" são parentes próximos: primos ou, segundo outra tradição antiga, filhos de José de um casamento anterior.', explanationEn: 'The Church professes Mary "ever virgin", before, during and after the birth of Jesus (Catechism §499-501). The title appears at the Second Council of Constantinople (553), and the Lateran Synod (649) expressly declared it. The "brothers of Jesus" are close relatives: cousins or, according to another ancient tradition, sons of Joseph by an earlier marriage.' },
  { id: 'tf-sete-sacramentos', statement: 'A Igreja Católica tem sete sacramentos.', statementEn: 'The Catholic Church has seven sacraments.', answer: true, explanation: 'Batismo, Confirmação, Eucaristia, Penitência, Unção dos Enfermos, Ordem e Matrimônio. Definido solenemente pelo Concílio de Trento (1547).', explanationEn: 'Baptism, Confirmation, Eucharist, Penance, Anointing of the Sick, Holy Orders, and Matrimony. Solemnly defined by the Council of Trent (1547).' },
  { id: 'tf-protestantes-5sacramentos', statement: 'A maioria das igrejas protestantes reconhece cinco sacramentos.', statementEn: 'Most Protestant churches recognize five sacraments.', answer: false, explanation: 'A maioria das denominações protestantes reconhece apenas dois: Batismo e Ceia do Senhor (Eucaristia), baseando-se em instituição explícita por Cristo nos Evangelhos.', explanationEn: 'Most Protestant denominations recognize only two: Baptism and the Lord\'s Supper (Eucharist), based on explicit institution by Christ in the Gospels.' },
  { id: 'tf-niceia-trindade', statement: 'O Concílio de Niceia (325) definiu a doutrina da Trindade em sua forma completa.', statementEn: 'The Council of Nicaea (325) defined the doctrine of the Trinity in its complete form.', answer: false, explanation: 'Niceia definiu a consubstancialidade do Filho. A doutrina sobre o Espírito Santo foi completada no Concílio de Constantinopla I (381), que afirmou a sua divindade.', explanationEn: 'Nicaea defined the consubstantiality of the Son. The full doctrine of the Trinity (including the Holy Spirit) was completed at Constantinople I (381) with the divinity of the Holy Spirit.' },
  { id: 'tf-jesuitas-inacio', statement: 'A Companhia de Jesus (Jesuítas) foi fundada por Santo Inácio de Loyola.', statementEn: 'The Society of Jesus (Jesuits) was founded by St. Ignatius of Loyola.', answer: true, explanation: 'Inácio de Loyola fundou a Companhia de Jesus em 1540, aprovada pelo Papa Paulo III. Os Jesuítas foram fundamentais na Contrarreforma e nas missões (Francisco Xavier na Ásia, José de Anchieta no Brasil).', explanationEn: 'Ignatius of Loyola founded the Society of Jesus in 1540, approved by Pope Paul III. The Jesuits were central to the Counter-Reformation and missions (Francis Xavier in Asia, José de Anchieta in Brazil).' },
  { id: 'tf-francisco-dominicanos', statement: 'São Francisco de Assis fundou a ordem dos Dominicanos.', statementEn: 'St. Francis of Assisi founded the Dominican Order.', answer: false, explanation: 'São Francisco fundou os Franciscanos (Ordem dos Frades Menores, ~1209). Os Dominicanos foram fundados por São Domingos de Gusmão (~1216), com foco na pregação e no combate a heresias.', explanationEn: 'St. Francis founded the Franciscans (Order of Friars Minor, ~1209). The Dominicans were founded by St. Dominic (~1216), focused on preaching and combating heresies.' },
  { id: 'tf-adoracao-santos', statement: 'Católicos adoram os santos da mesma forma que adoram a Deus.', statementEn: 'Catholics worship the saints in the same way they worship God.', answer: false, explanation: 'A teologia católica distingue a latria (adoração, devida só a Deus), a hiperdulia (veneração especial a Maria) e a dulia (veneração comum aos santos). Pedir a intercessão de um santo é como pedir a um amigo que reze por você.', explanationEn: 'Catholic theology distinguishes latria (worship due to God alone), hyperdulia (special veneration for Mary), and dulia (common veneration for saints). Asking a saint\'s intercession is like asking a friend to pray for you.' },
  { id: 'tf-catecismo-comprimento', statement: 'O Catecismo da Igreja Católica tem mais de 2000 parágrafos.', statementEn: 'The Catechism of the Catholic Church has more than 2,000 paragraphs.', answer: true, explanation: 'O Catecismo (1992) tem 2.865 parágrafos, em quatro partes: o Credo, os Sacramentos, a Vida Moral e a Oração.', explanationEn: 'The Catechism (1992) has 2,865 paragraphs, in four parts: the Creed, the Sacraments, the Moral Life and Prayer.' },
  { id: 'tf-papas-casados', statement: 'Nenhum Papa da história foi casado.', statementEn: 'No Pope in history was ever married.', answer: false, explanation: 'Pedro era casado (Mt 8,14 menciona sua sogra), e houve outros papas casados ou viúvos, como Adriano II (867-872), cuja esposa ainda vivia quando ele foi eleito. A lei do celibato se firmou aos poucos no Ocidente.', explanationEn: 'Peter was married (Mt 8:14 mentions his mother-in-law), and there were other married or widowed popes, such as Adrian II (867-872), whose wife was still alive when he was elected. The law of celibacy took hold gradually in the West.' },
  { id: 'tf-credo-apostolico-apostolos', statement: 'O Credo Apostólico foi escrito pelos doze apóstolos, cada um contribuindo com uma frase.', statementEn: 'The Apostles\' Creed was written by the twelve apostles, each contributing one phrase.', answer: false, explanation: 'É uma lenda piedosa antiga, que Rufino de Aquileia já conta por volta de 404. O Credo Apostólico deriva do antigo Símbolo Romano (séc. II-III), usado no Batismo em Roma. Resume o ensinamento dos apóstolos, mas não foi composto por eles.', explanationEn: 'It is an ancient pious legend, already told by Rufinus of Aquileia around 404. The Apostles\' Creed derives from the old Roman Symbol (2nd-3rd century), used at Baptism in Rome. It sums up the apostles\' teaching, but was not composed by them.' },
  { id: 'tf-eucaristia-sacrificio', statement: 'A Eucaristia é o mesmo sacrifício do Calvário, re-apresentado de forma incruenta.', statementEn: 'The Eucharist is the same sacrifice of Calvary, re-presented in an unbloody manner.', answer: true, explanation: 'Concílio de Trento (1562): a Missa não é um sacrifício novo, mas o mesmo sacrifício do Calvário, tornando presente o que ocorreu uma vez para sempre na Cruz (Hb 10,10).', explanationEn: 'Council of Trent (1562): the Mass is not a new sacrifice, but the same sacrifice of Calvary, making present what occurred once for all on the Cross (Heb 10:10).' },
  { id: 'tf-papa-bispo-roma', statement: 'O primado do Papa se baseia no fato de ele ser o Bispo de Roma.', statementEn: 'The Pope\'s primacy is based on the fact that he is the Bishop of Rome.', answer: true, explanation: 'O papa é o sucessor de Pedro como Bispo de Roma, cidade onde Pedro pregou e foi martirizado. O primado romano tem base tanto na sucessão petrina (Mt 16,18) quanto na sede apostólica de Roma.', explanationEn: 'The pope is Peter\'s successor as Bishop of Rome, the city where Peter preached and was martyred. Roman primacy is based both on Petrine succession (Mt 16:18) and the apostolic see of Rome.' },
  { id: 'tf-aborto-ensino', statement: 'A Igreja Católica condena o aborto em qualquer circunstância.', statementEn: 'The Catholic Church condemns abortion in any circumstance.', answer: true, explanation: 'O Catecismo (§2271) ensina que o aborto direto, "querido como fim ou como meio, é gravemente contrário à lei moral", e não há exceção para ele. Outra coisa é uma intervenção necessária para tratar uma doença grave da mãe que, sem ser querida, causa a morte do feto: isso não entra na definição de aborto direto (Evangelium Vitae, 62).', explanationEn: 'The Catechism (§2271) teaches that direct abortion, "willed either as an end or a means, is gravely contrary to the moral law", and there is no exception for it. Something else is an intervention needed to treat a serious illness of the mother which, without being willed, causes the death of the fetus: that does not fall under the definition of direct abortion (Evangelium Vitae, 62).' },
  { id: 'tf-quran-jesus-profeta', statement: 'O Alcorão reconhece Jesus como profeta e messias.', statementEn: 'The Quran recognizes Jesus as a prophet and messiah.', answer: true, explanation: 'O Alcorão chama Jesus de "Isa al-Masih" (Jesus o Messias) e o considera um dos maiores profetas. Afirma seu nascimento virginal. Nega, porém, sua divindade e sua crucificação.', explanationEn: 'The Quran calls Jesus "Isa al-Masih" (Jesus the Messiah) and considers him one of the greatest prophets. It affirms his virginal birth. However, it denies his divinity and crucifixion.' },
  { id: 'tf-igrejas-orientais-comunhao', statement: 'As Igrejas Católicas Orientais (como a Greco-Católica Ucraniana) estão em plena comunhão com Roma.', statementEn: 'The Eastern Catholic Churches (like the Ukrainian Greek Catholic Church) are in full communion with Rome.', answer: true, explanation: 'As Igrejas Católicas Orientais mantêm seus próprios ritos, teologia e disciplina (como o clero casado), mas estão em plena comunhão com o Papa. Não confundir com as Igrejas Ortodoxas, que não estão em comunhão.', explanationEn: 'Eastern Catholic Churches maintain their own rites, theology, and discipline (including married clergy), but are in full communion with the Pope. Not to be confused with Orthodox Churches, which are not in communion.' },
  { id: 'tf-pecado-original-adao', statement: 'O pecado original é transmitido pela imitação dos pecados de Adão, não por natureza.', statementEn: 'Original sin is transmitted by imitation of Adam\'s sins, not by nature.', answer: false, explanation: 'Era a tese ligada a Pelágio (séc. V), para quem o pecado de Adão passaria só pelo mau exemplo. O Concílio de Cartago (418) e depois o de Trento (1546) ensinaram que o pecado original se transmite pela propagação da natureza humana, "não por imitação".', explanationEn: 'This was the view associated with Pelagius (5th century), for whom Adam\'s sin was passed on only through bad example. The Council of Carthage (418) and later the Council of Trent (1546) taught that original sin is transmitted by the propagation of human nature, "not by imitation".' },
  { id: 'tf-comunhao-protestante', statement: 'Qualquer protestante pode comungar numa Missa católica sempre que quiser.', statementEn: 'Any Protestant may receive Communion at a Catholic Mass whenever they wish.', answer: false, explanation: 'Pelo Código de Direito Canônico (cân. 844), a regra é dar a Comunhão aos católicos. Outros cristãos só a recebem em casos previstos: os ortodoxos, se a pedirem espontaneamente e estiverem bem dispostos, e os demais, em perigo de morte ou outra necessidade grave, sem acesso ao próprio ministro e manifestando a fé católica na Eucaristia. A Eucaristia é sinal de uma unidade plena que ainda não existe.', explanationEn: 'Under the Code of Canon Law (can. 844), the rule is to give Communion to Catholics. Other Christians receive it only in specified cases: the Orthodox, if they ask of their own accord and are properly disposed, and others in danger of death or other grave necessity, without access to their own minister and manifesting Catholic faith in the Eucharist. The Eucharist is a sign of a full unity that does not yet exist.' },
  { id: 'tf-anjos-criaturas', statement: 'Os anjos são seres espirituais criados por Deus, superiores em natureza aos humanos.', statementEn: 'Angels are spiritual beings created by God, superior in nature to humans.', answer: true, explanation: 'O Catecismo (§328-330) ensina que os anjos são criaturas puramente espirituais, pessoais e imortais, que superam em perfeição todas as criaturas visíveis. Por outro lado, o Filho de Deus assumiu a natureza humana, não a angélica (Hebreus 2,16).', explanationEn: 'The Catechism (§328-330) teaches that angels are purely spiritual creatures, personal and immortal, who surpass in perfection all visible creatures. On the other hand, the Son of God assumed human nature, not angelic nature (Hebrews 2:16).' },
  { id: 'tf-inquisicao-milhoes', statement: 'A Inquisição medieval matou milhões de pessoas.', statementEn: 'The medieval Inquisition killed millions of people.', answer: false, explanation: 'Não há base para "milhões". A maioria dos réus da Inquisição medieval recebia penitências: o inquisidor Bernardo Gui, em Toulouse (1308-1323), entregou ao braço secular cerca de 45 das mais de 600 pessoas que julgou. Para a Inquisição Espanhola (1478-1834), as estimativas ficam entre 3.000 e 5.000 execuções.', explanationEn: 'There is no basis for "millions". Most defendants of the medieval Inquisition received penances: the inquisitor Bernard Gui, in Toulouse (1308-1323), handed over to the secular arm about 45 of the more than 600 people he judged. For the Spanish Inquisition (1478-1834), estimates range between 3,000 and 5,000 executions.' },
  { id: 'tf-criacao-ex-nihilo', statement: 'A criação "ex nihilo" (do nada) é doutrina católica, negada pelo ateísmo e por algumas heresias antigas.', statementEn: 'Creation "ex nihilo" (from nothing) is Catholic doctrine, denied by atheism and some ancient heresies.', answer: true, explanation: 'O IV Concílio de Latrão (1215) professa que Deus fez do nada as criaturas espirituais e corporais, e 2 Macabeus 7,28 já diz que Deus criou tudo "do nada". Filósofos gregos e o herege Hermógenes, combatido por Tertuliano (por volta de 200), afirmavam uma matéria eterna.', explanationEn: 'The Fourth Lateran Council (1215) professes that God made spiritual and corporeal creatures out of nothing, and 2 Maccabees 7:28 already says that God made everything "out of nothing". Greek philosophers and the heretic Hermogenes, opposed by Tertullian (around 200), held that matter was eternal.' },
  { id: 'tf-sacerdotes-confessar-pecados', statement: 'Sacerdotes católicos podem confessar seus pecados a outros sacerdotes.', statementEn: 'Catholic priests can confess their sins to other priests.', answer: true, explanation: 'Todo fiel, inclusive padres, bispos e o Papa, recebe o sacramento da Reconciliação de outro sacerdote, já que ninguém pode absolver a si mesmo. São João Paulo II, segundo seus colaboradores, confessava-se com frequência.', explanationEn: 'Every member of the faithful, including priests, bishops and the Pope, receives the sacrament of Reconciliation from another priest, since no one can absolve himself. St. John Paul II, according to those close to him, went to confession frequently.' },
  { id: 'tf-missa-latin-obrigatorio', statement: 'Desde o Concílio Vaticano II, a Missa deve ser celebrada exclusivamente em latim.', statementEn: 'Since Vatican II, Mass must be celebrated exclusively in Latin.', answer: false, explanation: 'O Vaticano II manteve o latim como língua do rito latino, mas permitiu as línguas vernáculas (Sacrosanctum Concilium 36). A Missa de Paulo VI tem edição típica em latim e é celebrada sobretudo nas línguas locais. O uso do missal anterior (tridentino) foi ampliado por Bento XVI em 2007 e voltou a ser restringido por Francisco em 2021 (Traditionis Custodes).', explanationEn: 'Vatican II kept Latin as the language of the Latin rite but permitted vernacular languages (Sacrosanctum Concilium 36). The Mass of Paul VI has a typical edition in Latin and is celebrated mostly in local languages. Use of the earlier (Tridentine) missal was broadened by Benedict XVI in 2007 and restricted again by Francis in 2021 (Traditionis Custodes).' },
  { id: 'tf-limbo-dogma', statement: 'O Limbo das crianças (para bebês não batizados) é dogma definido da Igreja Católica.', statementEn: 'The Limbo of children (for unbaptized infants) is a defined dogma of the Catholic Church.', answer: false, explanation: 'O limbo é uma hipótese teológica e nunca foi dogma. A Comissão Teológica Internacional (2007) disse que ele "permanece uma hipótese teológica possível", mas que há razões sérias para esperar a salvação das crianças que morrem sem Batismo. O Catecismo (§1261) as confia à misericórdia de Deus.', explanationEn: 'Limbo is a theological hypothesis and was never a dogma. The International Theological Commission (2007) said that it "remains a possible theological hypothesis", but that there are serious grounds to hope for the salvation of infants who die without Baptism. The Catechism (§1261) entrusts them to the mercy of God.' },
  { id: 'tf-pedro-primeiro-papa', statement: 'São Pedro é considerado pela Igreja Católica como o primeiro Papa.', statementEn: 'St. Peter is considered by the Catholic Church to be the first Pope.', answer: true, explanation: 'Jesus disse: "tu és Pedro, e sobre esta pedra edificarei a minha Igreja; as portas do inferno não prevalecerão contra ela" (Mt 16,18). A tradição o conta como primeiro bispo de Roma, onde morreu mártir sob Nero, por volta de 64-67 d.C.', explanationEn: 'Jesus said: "thou art Peter; and upon this rock I will build my church, and the gates of hell shall not prevail against it" (Mt 16:18). Tradition counts him as the first bishop of Rome, where he died a martyr under Nero, around 64-67 AD.' },
  { id: 'tf-darwin-catolicismo', statement: 'Charles Darwin foi excomungado pela Igreja Católica por causa da teoria da evolução.', statementEn: 'Charles Darwin was excommunicated by the Catholic Church because of the theory of evolution.', answer: false, explanation: 'Darwin, batizado na Igreja da Inglaterra, nem era católico, e A Origem das Espécies nunca entrou no Índice de Livros Proibidos. Ele foi sepultado na Abadia de Westminster (anglicana). Houve críticos da teoria em várias igrejas, mas a Igreja Católica nunca a condenou como heresia.', explanationEn: 'Darwin, baptized in the Church of England, was not even Catholic, and On the Origin of Species was never placed on the Index of Forbidden Books. He was buried in Westminster Abbey (Anglican). The theory had critics in various churches, but the Catholic Church never condemned it as heresy.' },
  { id: 'tf-indulgencias-pecados', statement: 'As indulgências permitem ao fiel comprar o perdão dos pecados.', statementEn: 'Indulgences allow the faithful to purchase the forgiveness of sins.', answer: false, explanation: 'As indulgências remitem a pena temporal devida por pecados já perdoados (Catecismo §1471). Não perdoam pecados, o que se faz na Confissão. Abusos na pregação de indulgências ligadas a esmolas, como a de Johann Tetzel, estiveram entre os estopins da Reforma, e o Concílio de Trento suprimiu os "pregadores de esmolas" (1562).', explanationEn: 'Indulgences remit the temporal punishment due to sins already forgiven (Catechism §1471). They do not forgive sins; that is done in Confession. Abuses in preaching indulgences tied to alms, such as Johann Tetzel\'s, were among the triggers of the Reformation, and the Council of Trent abolished the "alms-collectors" (1562).' },
  { id: 'tf-credo-nicea-espiritu', statement: 'O Credo de Niceia-Constantinopla inclui afirmações sobre o Espírito Santo.', statementEn: 'The Nicene-Constantinopolitan Creed includes statements about the Holy Spirit.', answer: true, explanation: 'O Credo de Niceia (325) só dizia "e no Espírito Santo". O de Constantinopla (381) acrescentou: "Senhor que dá a vida, procede do Pai e com o Pai e o Filho é adorado e glorificado". O "e do Filho" (Filioque) foi acrescentado depois, no Ocidente.', explanationEn: 'The Creed of Nicaea (325) only said "and in the Holy Spirit". That of Constantinople (381) added: "the Lord, the giver of life, who proceeds from the Father, who with the Father and the Son is adored and glorified". The "and the Son" (Filioque) was added later in the West.' },
  { id: 'tf-mormoes-deus-humano', statement: 'Os Mórmons creem que Deus foi outrora um ser humano que evoluiu para a divindade.', statementEn: 'Mormons believe God was once a human being who evolved into divinity.', answer: true, explanation: 'Joseph Smith ensinou no Discurso de King Follett (1844) que Deus "já foi como nós somos agora", e Lorenzo Snow, depois presidente da igreja, resumiu: "Como o homem é, Deus foi; como Deus é, o homem pode vir a ser". Isso é incompatível com o monoteísmo cristão, para o qual Deus é eterno e imutável.', explanationEn: 'Joseph Smith taught in the King Follett Discourse (1844) that God "was once as we are now", and Lorenzo Snow, later president of the church, summed it up: "As man now is, God once was; as God now is, man may be". This is incompatible with Christian monotheism, for which God is eternal and unchanging.' },
  { id: 'tf-vaticano-estado', statement: 'A Cidade do Vaticano é um Estado soberano reconhecido internacionalmente.', statementEn: 'Vatican City is a sovereign state recognized internationally.', answer: true, explanation: 'Pelo Tratado de Latrão (1929), a Itália reconheceu a soberania da Santa Sé sobre a Cidade do Vaticano (0,44 km²). O Vaticano tem passaportes, moeda, rádio, jornal e representações diplomáticas.', explanationEn: 'By the Lateran Treaty (1929), Italy recognized the sovereignty of the Holy See over Vatican City (0.44 km²). The Vatican has passports, currency, radio, newspaper, and diplomatic missions.' },
  { id: 'tf-hebreus-paulo', statement: 'A autoria da Carta aos Hebreus por Paulo é considerada certa pela Igreja Católica.', statementEn: 'The authorship of the Letter to the Hebrews by Paul is considered certain by the Catholic Church.', answer: false, explanation: 'Orígenes (séc. III) dizia: "quem escreveu a carta, na verdade, só Deus sabe" (citado por Eusébio). O Concílio de Trento a lista entre as catorze cartas de Paulo, mas o que ele define é a canonicidade, e hoje a autoria é tratada como questão aberta. Os candidatos incluem Paulo, Apolo, Barnabé e Priscila.', explanationEn: 'Origen (3rd century) said: "who wrote the epistle, in truth God knows" (quoted by Eusebius). The Council of Trent lists it among the fourteen letters of Paul, but what it defines is canonicity, and today authorship is treated as an open question. Candidates include Paul, Apollos, Barnabas and Priscilla.' },
  { id: 'tf-mateus-primeiro-evangelho', statement: 'O Evangelho de Mateus foi o primeiro a ser escrito, segundo o consenso atual da crítica bíblica.', statementEn: 'The Gospel of Matthew was the first to be written, according to current biblical scholarship.', answer: false, explanation: 'A posição majoritária hoje é que Marcos foi escrito primeiro (por volta de 65-75 d.C.) e que Mateus e Lucas o usaram como fonte (hipótese das duas fontes). A tradição dos Padres punha Mateus em primeiro lugar, e alguns estudiosos ainda a defendem. A conclusão majoritária vem da comparação dos textos, não dos manuscritos.', explanationEn: 'The majority view today is that Mark was written first (around 65-75 AD) and that Matthew and Luke used it as a source (two-source hypothesis). The tradition of the Fathers placed Matthew first, and some scholars still defend it. The majority conclusion comes from comparing the texts, not from the manuscripts.' },
  { id: 'tf-exorcismo-existe', statement: 'A Igreja Católica possui um rito oficial de exorcismo.', statementEn: 'The Catholic Church has an official rite of exorcism.', answer: true, explanation: 'O Ritual Romano traz o rito do exorcismo maior, revisto em 1999 (De exorcismis et supplicationibus quibusdam). Só pode realizá-lo o sacerdote autorizado expressamente pelo bispo (Código de Direito Canônico, cân. 1172; Catecismo §1673). Jesus expulsou demônios (Mt 8,28-34).', explanationEn: 'The Roman Ritual contains the rite of major exorcism, revised in 1999 (De exorcismis et supplicationibus quibusdam). Only a priest expressly authorized by the bishop may perform it (Code of Canon Law, can. 1172; Catechism §1673). Jesus cast out demons (Mt 8:28-34).' },
  { id: 'tf-filioque', statement: 'O "Filioque" ("e do Filho") no Credo Niceno é uma das causas do Cisma entre Ocidente e Oriente (1054).', statementEn: 'The "Filioque" ("and the Son") in the Nicene Creed is one of the causes of the Schism between East and West (1054).', answer: true, explanation: 'O Ocidente acrescentou ao Credo o "Filioque" (o Espírito procede do Pai "e do Filho"), primeiro na Espanha (Toledo, 589) e em Roma só em 1014, sem um concílio ecumênico. O Oriente viu nisso uma alteração indevida do Credo e um erro doutrinal. Junto com questões de jurisdição, isso contribuiu para o Cisma de 1054.', explanationEn: 'The West added the "Filioque" to the Creed (the Spirit proceeds from the Father "and the Son"), first in Spain (Toledo, 589) and in Rome only in 1014, without an ecumenical council. The East saw this as an improper alteration of the Creed and a doctrinal error. Together with questions of jurisdiction, it contributed to the Schism of 1054.' },
  { id: 'tf-santa-ceia-simbolo', statement: 'Toda denominação cristã concorda que a Ceia do Senhor é apenas um símbolo ou memorial.', statementEn: 'Every Christian denomination agrees that the Lord\'s Supper is only a symbol or memorial.', answer: false, explanation: 'Católicos e ortodoxos professam a presença real de Cristo. Luteranos afirmam a presença real "em, com e sob" o pão e o vinho (o termo "consubstanciação" lhes é atribuído, mas eles costumam rejeitá-lo). Calvino ensinava uma presença espiritual real. O puro simbolismo vem de Zuínglio e é comum entre batistas e muitas igrejas evangélicas.', explanationEn: 'Catholics and Orthodox profess the real presence of Christ. Lutherans affirm the real presence "in, with and under" the bread and wine (the term "consubstantiation" is attributed to them, but they usually reject it). Calvin taught a real spiritual presence. Pure symbolism comes from Zwingli and is common among Baptists and many evangelical churches.' },
  { id: 'tf-bible-literacy', statement: 'A Igreja Católica medieval proibia os leigos de ler a Bíblia.', statementEn: 'The medieval Catholic Church forbade laypeople from reading the Bible.', answer: false, explanation: 'Não houve proibição geral. Houve restrições locais, como as do Sínodo de Toulouse (1229) contra as traduções usadas pelos cátaros, e circulavam traduções medievais em várias línguas. Antes da imprensa, Bíblias eram caras e raras, e a maioria não sabia ler. Monges e leigos instruídos rezavam diariamente os Salmos.', explanationEn: 'There was no general prohibition. There were local restrictions, such as those of the Synod of Toulouse (1229) against translations used by the Cathars, and medieval translations circulated in several languages. Before printing, Bibles were expensive and rare, and most people could not read. Monks and educated laypeople prayed the Psalms daily.' },
  { id: 'tf-uniao-hipostatica', statement: 'A "união hipostática" refere-se à união das duas naturezas de Cristo em uma única pessoa divina.', statementEn: 'The "hypostatic union" refers to the union of Christ\'s two natures in one divine person.', answer: true, explanation: 'Definida em Calcedônia (451): Jesus é uma única pessoa (hypóstasis) em duas naturezas, divina e humana, completas e sem confusão. É a fórmula central da cristologia católica e ortodoxa.', explanationEn: 'Defined at Chalcedon (451): Jesus is one person (hypostasis) in two natures, divine and human, complete and without confusion. It is the central formula of Catholic and Orthodox Christology.' },
  { id: 'tf-orar-mortos', statement: 'Rezar pelos mortos (sufrágio) não tem nenhuma base na Sagrada Escritura.', statementEn: 'Praying for the dead (suffrages) has no basis in Sacred Scripture.', answer: false, explanation: '2 Macabeus 12,43-46 narra Judas Macabeu mandando oferecer um sacrifício expiatório pelos soldados mortos. O Novo Testamento não proíbe a prática, e Paulo pede ao Senhor misericórdia para Onesíforo, que provavelmente já tinha morrido (2 Tm 1,16-18).', explanationEn: '2 Maccabees 12:43-46 recounts Judas Maccabeus having an expiatory sacrifice offered for the fallen soldiers. The New Testament does not forbid the practice, and Paul asks the Lord\'s mercy for Onesiphorus, who had probably already died (2 Tm 1:16-18).' },
  { id: 'tf-concilio-vatII-dogma', statement: 'O Concílio Vaticano II definiu novos dogmas de fé.', statementEn: 'The Second Vatican Council defined new dogmas of faith.', answer: false, explanation: 'O Vaticano II ensinou com autoridade, inclusive em duas constituições dogmáticas (Lumen Gentium e Dei Verbum), mas não proclamou dogmas novos de forma solene e infalível. A nota anexa à Lumen Gentium explica que, dado o fim pastoral do concílio, ele só define como de fé o que declara abertamente como tal.', explanationEn: 'Vatican II taught with authority, including in two dogmatic constitutions (Lumen Gentium and Dei Verbum), but did not solemnly and infallibly proclaim new dogmas. The note appended to Lumen Gentium explains that, given the council\'s pastoral aim, it defines as matters of faith only what it openly declares as such.' },
  { id: 'tf-apocalipse-joao', statement: 'Que o Apocalipse foi escrito pelo mesmo João do Quarto Evangelho é questão debatida desde a Antiguidade.', statementEn: 'Whether Revelation was written by the same John as the Fourth Gospel has been debated since antiquity.', answer: true, explanation: 'São Justino (por volta de 155) e Santo Ireneu (por volta de 180) atribuem o livro ao apóstolo João. Já Dionísio de Alexandria (séc. III) notou que o grego é muito diferente do Evangelho e pensou em outro João. Muitos estudiosos hoje distinguem os autores, e a Igreja recebe o livro como canônico sem definir a questão.', explanationEn: 'St. Justin (around 155) and St. Irenaeus (around 180) attribute the book to the apostle John. Dionysius of Alexandria (3rd century), however, noted that its Greek is very different from the Gospel\'s and thought of another John. Many scholars today distinguish the authors, and the Church receives the book as canonical without settling the question.' },
  { id: 'tf-corpus-christi', statement: 'A festa de Corpus Christi foi instituída após uma visão de Santa Juliana de Liège.', statementEn: 'The Feast of Corpus Christi was instituted following a vision of St. Juliana of Liège.', answer: true, explanation: 'Santa Juliana de Liège (séc. XIII) relatou visões pedindo uma festa para a Eucaristia, celebrada em Liège desde 1246. O Papa Urbano IV a estendeu a toda a Igreja em 1264 (bula Transiturus). A tradição atribui a São Tomás de Aquino os textos da festa, como o Pange lingua (cujas duas últimas estrofes formam o Tantum ergo) e a sequência Lauda Sion.', explanationEn: 'St. Juliana of Liège (13th century) reported visions asking for a feast of the Eucharist, celebrated in Liège from 1246. Pope Urban IV extended it to the whole Church in 1264 (bull Transiturus). Tradition attributes the texts of the feast to St. Thomas Aquinas, such as the Pange lingua (whose last two stanzas form the Tantum ergo) and the sequence Lauda Sion.' },
  { id: 'tf-morte-cerebral-eutanasia', statement: 'A Igreja Católica considera a morte cerebral como critério lícito para declarar a morte de uma pessoa.', statementEn: 'The Catholic Church considers brain death as a licit criterion for declaring a person dead.', answer: true, explanation: 'Em 2000, João Paulo II disse que o critério da cessação completa e irreversível de toda atividade cerebral, se aplicado com rigor, não contradiz os elementos essenciais de uma antropologia séria. A Pontifícia Academia das Ciências também o aceita. A Igreja apoia a doação de órgãos como ato de caridade (Catecismo §2296).', explanationEn: 'In 2000 John Paul II said that the criterion of the complete and irreversible cessation of all brain activity, if rigorously applied, "does not seem to conflict with the essential elements of a sound anthropology". The Pontifical Academy of Sciences also accepts it. The Church supports organ donation as an act of charity (Catechism §2296).' },
  { id: 'tf-espiritos-malignos', statement: 'A Igreja Católica ensina que demônios existem como seres reais, não apenas como símbolos do mal.', statementEn: 'The Catholic Church teaches that demons exist as real beings, not merely as symbols of evil.', answer: true, explanation: 'O Catecismo (§391-395) ensina que Satanás e os demônios são anjos criados bons que se tornaram maus por livre escolha. Jesus expulsou demônios (Mc 1,34). O exorcismo é um rito oficial da Igreja (Rituale Romanum).', explanationEn: 'The Catechism (§391-395) teaches that Satan and demons are good angels who became evil by free choice. Jesus cast out demons (Mk 1:34). Exorcism is an official rite of the Church (Rituale Romanum).' },
  { id: 'tf-aborto-excomunhao', statement: 'Quem procura ou realiza um aborto incorre automaticamente em excomunhão na Igreja Católica.', statementEn: 'Those who procure or perform an abortion automatically incur excommunication in the Catholic Church.', answer: true, explanation: 'Pelo Código de Direito Canônico (cân. 1397 §2, na revisão de 2021; antes, cân. 1398), quem procura o aborto, consumado o efeito, incorre em excomunhão automática (latae sententiae). Atenuantes previstas no Código, como ter menos de 16 anos ou ignorar a pena, impedem a excomunhão (cân. 1323-1324). Desde 2016 (Misericordia et misera), todo sacerdote pode absolver esse pecado.', explanationEn: 'Under the Code of Canon Law (can. 1397 §2, in the 2021 revision; formerly can. 1398), anyone who procures an abortion, if it is carried out, incurs automatic (latae sententiae) excommunication. Mitigating factors set out in the Code, such as being under 16 or not knowing of the penalty, prevent the excommunication (can. 1323-1324). Since 2016 (Misericordia et misera), every priest may absolve this sin.' },
  { id: 'tf-islam-cinco-pilares', statement: 'Os cinco pilares do islã incluem a crença em Allah e Maomé, oração, jejum, esmola e peregrinação.', statementEn: 'The five pillars of Islam include belief in Allah and Muhammad, prayer, fasting, almsgiving, and pilgrimage.', answer: true, explanation: 'Os cinco pilares (Arkan al-Islam): Shahada (profissão de fé), Salat (5 orações diárias), Zakat (esmola), Sawm (jejum do Ramadã) e Hajj (peregrinação a Meca). Estrutura básica da prática islâmica.', explanationEn: 'The five pillars (Arkan al-Islam): Shahada (profession of faith), Salat (5 daily prayers), Zakat (almsgiving), Sawm (Ramadan fast), and Hajj (pilgrimage to Mecca). The basic structure of Islamic practice.' },
  { id: 'tf-protestantes-oracao-mortos', statement: 'As principais denominações protestantes ensinam a oração pelos mortos.', statementEn: 'The main Protestant denominations teach prayer for the dead.', answer: false, explanation: 'A maioria dos protestantes rejeita a oração pelos mortos, por entender que o destino eterno se fixa na morte e por rejeitar o purgatório. Rezam pelos mortos a Igreja Católica, as Igrejas Ortodoxas (que não usam a noção de purgatório) e parte dos anglicanos e luteranos.', explanationEn: 'Most Protestants reject prayer for the dead, holding that eternal destiny is fixed at death and rejecting purgatory. Prayer for the dead is practiced by the Catholic Church, the Orthodox Churches (which do not use the notion of purgatory) and some Anglicans and Lutherans.' },
  { id: 'tf-sacerdocio-universal', statement: 'O sacerdócio universal dos fiéis (1 Pd 2,9) elimina a necessidade do sacerdócio ministerial ordenado.', statementEn: 'The universal priesthood of the faithful (1 Pt 2:9) eliminates the need for ordained ministerial priesthood.', answer: false, explanation: 'O Vaticano II (Lumen Gentium, n. 10) ensina que o sacerdócio comum dos fiéis e o sacerdócio ministerial, embora "se diferenciem essencialmente e não apenas em grau", estão ordenados um ao outro. Um não substitui o outro.', explanationEn: 'Vatican II (Lumen Gentium, no. 10) teaches that the common priesthood of the faithful and the ministerial priesthood, though they "differ from one another in essence and not only in degree", are ordered one to another. One does not replace the other.' },
  { id: 'tf-crisma-pentecostes-pessoal', statement: 'A Confirmação é chamada o "Pentecostes pessoal" de cada cristão.', statementEn: 'Confirmation is called the "personal Pentecost" of every Christian.', answer: true, explanation: 'O Catecismo (§1302) diz que o efeito da Confirmação é uma efusão especial do Espírito Santo, "tal como outrora foi concedida aos Apóstolos, no dia de Pentecostes". Daí a imagem, comum na catequese, do "Pentecostes pessoal". O sacramento completa a graça do Batismo e fortalece para o testemunho.', explanationEn: 'The Catechism (§1302) says that the effect of Confirmation is the special outpouring of the Holy Spirit "as once granted to the apostles on the day of Pentecost". Hence the image, common in catechesis, of a "personal Pentecost". The sacrament completes baptismal grace and strengthens one for witness.' },
  { id: 'tf-velho-testamento-abolido', statement: 'Segundo Mateus 5,17, Jesus veio abolir a Lei e os Profetas.', statementEn: 'According to Matthew 5:17, Jesus came to abolish the Law and the Prophets.', answer: false, explanation: 'É o contrário: "Não julgueis que vim abolir a Lei ou os profetas. Não vim para os abolir, mas sim para levá-los à perfeição" (Mt 5,17). Jesus cumpre em si o Antigo Testamento (profecias, figuras, lei), que continua sendo Palavra de Deus, agora lida à luz de Cristo.', explanationEn: 'It is the opposite: "Do not think that I am come to destroy the law, or the prophets. I am not come to destroy, but to fulfil" (Mt 5:17). Jesus fulfills the Old Testament in himself (prophecies, figures, law), which remains the Word of God, now read in the light of Christ.' },
  { id: 'tf-maria-medianeira', statement: 'O título "Mediadora de Todas as Graças" para Maria é dogma definido da Igreja Católica.', statementEn: 'The title "Mediatrix of All Graces" for Mary is a defined dogma of the Catholic Church.', answer: false, explanation: 'Não é dogma. Em 2025, a nota doutrinal Mater Populi Fidelis, do Dicastério para a Doutrina da Fé, aprovada por Leão XIV, disse que o título "Medianeira de todas as graças" tem limites e pode sugerir Maria distribuindo graças à parte da relação com Cristo, embora admita um sentido aceitável para a sua ajuda materna. O único mediador entre Deus e os homens é Cristo (1 Tm 2,5).', explanationEn: 'It is not a dogma. In 2025 the doctrinal note Mater Populi Fidelis, from the Dicastery for the Doctrine of the Faith, approved by Leo XIV, said that the title "Mediatrix of All Graces" has limits and may suggest Mary distributing graces apart from our relationship with Christ, while allowing an acceptable sense for her maternal help. The one mediator between God and men is Christ (1 Tm 2:5).' },
  { id: 'tf-catolicismo-maior-religiao', statement: 'O catolicismo romano é a maior denominação cristã do mundo.', statementEn: 'Roman Catholicism is the largest Christian denomination in the world.', answer: true, explanation: 'Com cerca de 1,42 bilhão de fiéis no fim de 2024 (Anuário Pontifício 2026), a Igreja Católica é a maior denominação cristã do mundo, presente em praticamente todos os países.', explanationEn: 'With about 1.42 billion faithful at the end of 2024 (Annuario Pontificio 2026), the Catholic Church is the largest Christian denomination in the world, present in virtually every country.' },
  { id: 'tf-ccc-novo-testamento', statement: 'O Novo Testamento foi escrito completamente em grego koiné.', statementEn: 'The New Testament was written entirely in Koine Greek.', answer: true, explanation: 'Os 27 livros chegaram até nós em grego koiné, a língua comum do Mediterrâneo no séc. I, e não em aramaico (que Jesus falava) nem em hebraico. Papias (séc. II) diz que Mateus compôs em "dialeto hebraico", mas o Evangelho de Mateus que conhecemos foi escrito em grego.', explanationEn: 'The 27 books have come down to us in Koine Greek, the common language of the Mediterranean in the 1st century, not in Aramaic (which Jesus spoke) or Hebrew. Papias (2nd century) says Matthew composed in the "Hebrew dialect", but the Gospel of Matthew we know was written in Greek.' },
  { id: 'tf-missa-sacrificio-novo', statement: 'A Missa é um novo sacrifício diferente e adicional ao da Cruz.', statementEn: 'The Mass is a new and additional sacrifice different from that of the Cross.', answer: false, explanation: 'Concílio de Trento (1562): a Missa não é um sacrifício novo, mas o mesmo e único sacrifício do Calvário, tornado presente de modo incruento. Hebreus 10,10: fomos santificados "uma vez para sempre, pela oblação do corpo de Jesus Cristo".', explanationEn: 'Council of Trent (1562): the Mass is not a new sacrifice, but the same and only sacrifice of Calvary, made present in an unbloody manner. Hebrews 10:10: we have been sanctified "by the oblation of the body of Jesus Christ once".' },
  { id: 'tf-leitura-biblia-merito', statement: 'A leitura da Bíblia é altamente recomendada pelo Magistério da Igreja.', statementEn: 'Bible reading is highly recommended by the Church\'s Magisterium.', answer: true, explanation: 'A Dei Verbum (n. 25) exorta todos os fiéis à leitura frequente da Escritura, lembrando que ela "deve ser acompanhada de oração", e cita São Jerônimo: "a ignorância das Escrituras é ignorância de Cristo".', explanationEn: 'Dei Verbum (no. 25) urges all the faithful to read Scripture frequently, reminding them that "prayer should accompany the reading of Sacred Scripture", and quotes St. Jerome: "ignorance of the Scriptures is ignorance of Christ".' },
  { id: 'tf-santidade-todos', statement: 'A santidade é uma vocação universal para todos os batizados, não apenas para religiosos.', statementEn: 'Holiness is a universal vocation for all the baptized, not only for religious.', answer: true, explanation: 'A Lumen Gentium (n. 40) ensina que "os cristãos de qualquer estado ou ordem são chamados à plenitude da vida cristã e à perfeição da caridade". João Paulo II, na Novo Millennio Ineunte (2001, n. 31), pediu uma verdadeira "pedagogia da santidade".', explanationEn: 'Lumen Gentium (no. 40) teaches that "all the faithful of Christ of whatever rank or status, are called to the fullness of the Christian life and to the perfection of charity". John Paul II, in Novo Millennio Ineunte (2001, no. 31), called for a genuine "training in holiness".' },
  { id: 'tf-reforma-protestante-biblia', statement: 'A Reforma Protestante foi possibilitada em parte pela invenção da imprensa de Gutenberg.', statementEn: 'The Protestant Reformation was made possible in part by Gutenberg\'s printing press invention.', answer: true, explanation: 'Gutenberg desenvolveu a prensa de tipos móveis por volta de 1450. As 95 Teses de Lutero (1517) foram reimpressas e se espalharam pela Alemanha em poucas semanas, e seus panfletos estiveram entre os textos mais vendidos da época. A Reforma costuma ser descrita como o primeiro grande movimento amplificado pela imprensa.', explanationEn: 'Gutenberg developed movable-type printing around 1450. Luther\'s 95 Theses (1517) were reprinted and spread across Germany within a few weeks, and his pamphlets were among the best-selling texts of the time. The Reformation is often described as the first great movement amplified by print.' },
  { id: 'tf-pregacao-apostolos', statement: 'Os apóstolos pregaram o Evangelho apenas a judeus, nunca a gentios.', statementEn: 'The apostles preached the Gospel only to Jews, never to Gentiles.', answer: false, explanation: 'Em Atos 10, Pedro manda batizar o centurião romano Cornélio e sua casa, que eram gentios (At 10,48). Paulo se apresenta como "apóstolo dos pagãos" (Rm 11,13), e Jesus manda ensinar "a todas as nações" (Mt 28,19).', explanationEn: 'In Acts 10, Peter orders the Roman centurion Cornelius and his household, who were Gentiles, to be baptized (Acts 10:48). Paul calls himself "the apostle of the Gentiles" (Rom 11:13), and Jesus commands teaching "all nations" (Mt 28:19).' },
  { id: 'tf-paulo-escravidade', statement: 'Paulo ensinou que a escravidão é um bem social positivo e a apoiou explicitamente.', statementEn: 'Paul taught that slavery is a positive social good and explicitly supported it.', answer: false, explanation: 'Paulo afirma que em Cristo "já não há judeu nem grego, nem escravo nem livre" (Gl 3,28). Na carta a Filêmon, pede que receba Onésimo "não já como escravo, mas bem mais do que escravo, como irmão caríssimo" (Fm 16). Paulo agia dentro do seu contexto, sem um programa abolicionista formal.', explanationEn: 'Paul affirms that in Christ "there is neither bond nor free" (Gal 3:28). In the letter to Philemon, he asks him to receive Onesimus "not now as a servant, but instead of a servant, a most dear brother" (Phm 16). Paul acted within his context, without a formal abolitionist program.' },
  { id: 'tf-criacao-tempo', statement: 'O tempo em si foi criado por Deus junto com o universo, não existia antes da criação.', statementEn: 'Time itself was created by God along with the universe, it did not exist before creation.', answer: true, explanation: 'Santo Agostinho escreveu que "o mundo não foi feito no tempo, mas com o tempo" (A Cidade de Deus XI,6), e o IV Concílio de Latrão (1215) ensina que Deus criou tudo "desde o princípio do tempo". Na cosmologia padrão, o tempo também começa com o Big Bang, embora a física do primeiro instante siga em aberto.', explanationEn: 'St. Augustine wrote that "the world was not made in time, but with time" (City of God XI,6), and the Fourth Lateran Council (1215) teaches that God created everything "from the beginning of time". In standard cosmology, time also begins with the Big Bang, although the physics of the first instant remains open.' },
  { id: 'tf-teresa-avila-doutora', statement: 'Santa Teresa de Ávila e Santa Teresa de Lisieux são ambas Doutoras da Igreja.', statementEn: 'St. Teresa of Ávila and St. Thérèse of Lisieux are both Doctors of the Church.', answer: true, explanation: 'Teresa de Ávila foi a primeira mulher proclamada Doutora da Igreja, por Paulo VI (27 de setembro de 1970), seguida por Catarina de Sena poucos dias depois. Teresa de Lisieux recebeu o título em 1997, de João Paulo II. Hoje são 38 Doutores da Igreja, 4 deles mulheres (a quarta é Hildegarda de Bingen, 2012). O mais recente é São John Henry Newman (2025).', explanationEn: 'Teresa of Ávila was the first woman proclaimed a Doctor of the Church, by Paul VI (27 September 1970), followed by Catherine of Siena a few days later. Thérèse of Lisieux received the title in 1997, from John Paul II. Today there are 38 Doctors of the Church, 4 of them women (the fourth is Hildegard of Bingen, 2012). The most recent is St. John Henry Newman (2025).' },
  { id: 'tf-rezar-inimigos', statement: 'Jesus mandou rezar pelos inimigos e perseguidores.', statementEn: 'Jesus commanded praying for enemies and persecutors.', answer: true, explanation: 'Mateus 5,44: "amai vossos inimigos, fazei bem aos que vos odeiam, orai pelos que vos maltratam e perseguem". E Jesus continua: se amais só os que vos amam, que recompensa tereis? (Mt 5,46). É um dos ensinamentos mais radicais do Evangelho.', explanationEn: 'Matthew 5:44: "Love your enemies: do good to them that hate you: and pray for them that persecute and calumniate you". And Jesus goes on: if you love only those who love you, what reward shall you have? (Mt 5:46). It is one of the most radical teachings of the Gospel.' },
  { id: 'tf-seculo-iv-ecumenismo', statement: 'O movimento ecumênico moderno entre cristãos teve início principalmente no séc. XXI.', statementEn: 'The modern ecumenical movement among Christians began mainly in the 21st century.', answer: false, explanation: 'O ecumenismo moderno iniciou no séc. XX com a Conferência Missionária de Edimburgo (1910) e o Conselho Mundial de Igrejas (1948). O Vaticano II (1962-65) com o decreto "Unitatis Redintegratio" marcou a entrada oficial da Igreja Católica no diálogo.', explanationEn: 'Modern ecumenism began in the 20th century with the Edinburgh Missionary Conference (1910) and the World Council of Churches (1948). Vatican II (1962-65) with the decree "Unitatis Redintegratio" marked the official entry of the Catholic Church into dialogue.' },
  { id: 'tf-orar-linguas', statement: 'O dom de línguas descrito em 1 Coríntios 14 é idêntico ao dom de línguas de Atos 2.', statementEn: 'The gift of tongues described in 1 Corinthians 14 is identical to the gift of tongues in Acts 2.', answer: false, explanation: 'Em Atos 2 todos entendiam em seu próprio idioma (línguas conhecidas). Em 1 Cor 14 Paulo fala de um dom que exige interpretação e não edifica sem ela (glossolalia como oração pessoal). Muitos teólogos os distinguem.', explanationEn: 'In Acts 2 everyone understood in their own language (known tongues). In 1 Cor 14 Paul speaks of a gift requiring interpretation and not edifying without it (glossolalia as personal prayer). Many theologians distinguish them.' },
  { id: 'tf-catolicismo-razao', statement: 'A fé católica é contrária à razão e à filosofia.', statementEn: 'The Catholic faith is opposed to reason and philosophy.', answer: false, explanation: 'A Igreja sempre integrou fé e razão. Tomás de Aquino sintetizou Aristóteles com a fé cristã. João Paulo II em "Fides et Ratio" (1998): "fé e razão são como duas asas pelas quais o espírito humano se eleva à contemplação da verdade".', explanationEn: 'The Church has always integrated faith and reason. Thomas Aquinas synthesized Aristotle with Christian faith. John Paul II in "Fides et Ratio" (1998): "Faith and reason are like two wings on which the human spirit rises to the contemplation of truth".' },
  { id: 'tf-novo-testamento-aramaico', statement: 'Jesus falava aramaico, mas os apóstolos escreveram o Novo Testamento em hebraico.', statementEn: 'Jesus spoke Aramaic, but the apostles wrote the New Testament in Hebrew.', answer: false, explanation: 'Jesus falava aramaico, e os Evangelhos guardam algumas palavras dele: "Abbá", "Talitá cumi", "Eli, Eli, lammá sabactáni". Mas o Novo Testamento foi escrito em grego koiné, a língua comum do séc. I, para alcançar todo o Mediterrâneo.', explanationEn: 'Jesus spoke Aramaic, and the Gospels preserve some of his words: "Abba", "Talitha kumi", "Eli, Eli, lama sabachthani". But the New Testament was written in Koine Greek, the common language of the 1st century, to reach the whole Mediterranean.' },
  { id: 'tf-pao-divido', statement: 'O "partir o pão" nos Atos dos Apóstolos refere-se à Eucaristia.', statementEn: 'The "breaking of bread" in the Acts of the Apostles refers to the Eucharist.', answer: true, explanation: 'Atos 2,42 diz que os primeiros cristãos "perseveravam na doutrina dos apóstolos, nas reuniões em comum, na fração do pão e nas orações" (veja também 2,46 e 20,7). O Catecismo (§1329) lista "fração do pão" entre os nomes da Eucaristia, citando esses textos.', explanationEn: 'Acts 2:42 says the first Christians "were persevering in the doctrine of the apostles and in the communication of the breaking of bread and in prayers" (see also 2:46 and 20:7). The Catechism (§1329) lists "breaking of bread" among the names of the Eucharist, citing these texts.' },
  { id: 'tf-jesus-politico', statement: 'Jesus tinha um programa político de libertação nacional de Israel do domínio romano.', statementEn: 'Jesus had a political program for the national liberation of Israel from Roman rule.', answer: false, explanation: 'Jesus se retirou quando quiseram fazê-lo rei (Jo 6,15), mandou dar "a César o que é de César" (Mt 22,21) e disse: "O meu Reino não é deste mundo" (Jo 18,36). Muitos esperavam um messias político, e Jesus ofereceu algo maior: a redenção.', explanationEn: 'Jesus withdrew when they wanted to make him king (Jn 6:15), told them to render "to Caesar the things that are Caesar\'s" (Mt 22:21) and said: "My kingdom is not of this world" (Jn 18:36). Many expected a political messiah, and Jesus offered something greater: redemption.' },
  { id: 'tf-biblia-completa-antes-jesus', statement: 'Toda a Bíblia (Antigo e Novo Testamento) já existia antes da vinda de Jesus.', statementEn: 'The entire Bible (Old and New Testaments) already existed before the coming of Jesus.', answer: false, explanation: 'Os 46 livros do Antigo Testamento já existiam. Os 27 do Novo foram escritos depois da Ressurreição, mais ou menos entre os anos 50 e 100, e a Igreja os reconheceu aos poucos: Atanásio (367) e os sínodos de Hipona (393) e Cartago (397) os listam, e Trento (1546) definiu o cânon.', explanationEn: 'The 46 books of the Old Testament already existed. The 27 of the New were written after the Resurrection, roughly between the years 50 and 100, and the Church recognized them gradually: Athanasius (367) and the synods of Hippo (393) and Carthage (397) list them, and Trent (1546) defined the canon.' },
  { id: 'tf-deus-criou-mal', statement: 'Deus criou o mal assim como criou o bem.', statementEn: 'God created evil just as he created good.', answer: false, explanation: 'Para Santo Agostinho, o mal não é uma substância criada, mas privação do bem (privatio boni). Deus criou só coisas boas, e o mal moral nasce do mau uso da liberdade das criaturas. Isaías 45,7 ("suscito a infelicidade", em outras traduções "crio o mal") fala de desgraças e castigos, não do mal moral.', explanationEn: 'For St. Augustine, evil is not a created substance but the privation of good (privatio boni). God created only good things, and moral evil arises from creatures\' misuse of freedom. Isaiah 45:7 ("I make peace, and create evil") speaks of calamities and punishments, not of moral evil.' },
  { id: 'tf-santos-olimpo', statement: 'A veneração de santos na Igreja Católica é uma sobrevivência do paganismo greco-romano.', statementEn: 'The veneration of saints in the Catholic Church is a survival of Greco-Roman paganism.', answer: false, explanation: 'A veneração dos mártires aparece já no séc. II: o Martírio de Policarpo (por volta de 156) fala de celebrar o aniversário de sua morte junto ao túmulo. Tem raízes bíblicas na honra aos justos e na "nuvem de testemunhas" de Hebreus 12,1. Não é adoração nem herança pagã.', explanationEn: 'Veneration of the martyrs appears as early as the 2nd century: the Martyrdom of Polycarp (around 156) speaks of celebrating the anniversary of his death at his tomb. It has biblical roots in honoring the righteous and in the "cloud of witnesses" of Hebrews 12:1. It is neither worship nor pagan heritage.' },
  { id: 'tf-livres-arbitrio-deus', statement: 'A Igreja Católica ensina que o livre-arbítrio humano é compatível com a providência divina.', statementEn: 'The Catholic Church teaches that human free will is compatible with divine providence.', answer: true, explanation: 'O Catecismo (§306-308) ensina que a providência divina governa tudo respeitando as causas livres. Deus não coage a vontade humana, mas coopera com ela. É um mistério, não uma contradição: Deus age como causa primeira, e a criatura como causa segunda.', explanationEn: 'The Catechism (§306-308) teaches that divine providence governs all things while respecting free causes. God does not coerce the human will but cooperates with it. It is a mystery, not a contradiction: God acts as first cause, and the creature as secondary cause.' },
  { id: 'tf-missa-sacrificio', statement: 'Segundo o Concílio de Trento, na Missa é o próprio Cristo que se oferece, pelo ministério dos sacerdotes.', statementEn: 'According to the Council of Trent, in the Mass it is Christ himself who offers himself, through the ministry of priests.', answer: true, explanation: 'Trento (sessão XXII, 1562) ensina que a vítima é uma só e a mesma: o mesmo Cristo que se ofereceu na Cruz agora se oferece pelo ministério dos sacerdotes, e só o modo de oferecer é diferente. O Catecismo (§1367) retoma esse texto.', explanationEn: 'Trent (session XXII, 1562) teaches that the victim is one and the same: the same Christ who offered himself on the Cross now offers himself through the ministry of priests, and only the manner of offering is different. The Catechism (§1367) takes up this text.' },
];




// Perguntas devocionais/reflexivas para o quiz diário (~uma por dia do ano).
export const DAILY_QUESTIONS = [
  { id: 'dq-001', question: 'Quantas pessoas existem na Santíssima Trindade?', questionEn: 'How many persons exist in the Holy Trinity?', options: ['Uma', 'Duas', 'Três', 'Incontáveis'], optionsEn: ['One', 'Two', 'Three', 'Countless'], correct: 2, why: 'Um só Deus em três pessoas: Pai, Filho e Espírito Santo. As três são coeternas e coiguais em natureza divina.', whyEn: 'One God in three persons: Father, Son, and Holy Spirit. All three are co-eternal and co-equal in divine nature.' },
  { id: 'dq-002', question: 'Qual é o primeiro mandamento do Decálogo?', questionEn: 'What is the first commandment of the Decalogue?', options: ['Honra pai e mãe', 'Não matarás', 'Não terás outros deuses além de mim', 'Guardar o sábado'], optionsEn: ['Honor your father and mother', 'You shall not kill', 'You shall have no other gods before me', 'Keep the Sabbath'], correct: 2, why: 'O primeiro mandamento (Ex 20,3) coloca Deus no centro absoluto da vida. Tudo mais decorre daí: se Deus é primeiro, os outros mandamentos fazem sentido.', whyEn: 'The first commandment (Ex 20:3) places God at the absolute center of life. Everything else flows from it: if God is first, the other commandments make sense.' },
  { id: 'dq-003', question: 'Qual é a oração que Jesus ensinou diretamente aos discípulos?', questionEn: 'What is the prayer Jesus taught directly to his disciples?', options: ['Ave Maria', 'Pai-Nosso', 'Gloria Patri', 'Salve Regina'], optionsEn: ['Hail Mary', 'Our Father', 'Glory Be', 'Hail Holy Queen'], correct: 1, why: 'Mateus 6,9-13 e Lucas 11,2-4 registram Jesus ensinando o Pai-Nosso. É a oração cristã por excelência, chamada por Tertuliano de "resumo de todo o Evangelho".', whyEn: 'Matthew 6:9-13 and Luke 11:2-4 record Jesus teaching the Our Father. It is the Christian prayer par excellence, called by Tertullian "the summary of the whole Gospel".' },
  { id: 'dq-004', question: 'Quantos livros tem o Novo Testamento?', questionEn: 'How many books does the New Testament have?', options: ['24', '27', '29', '33'], optionsEn: ['24', '27', '29', '33'], correct: 1, why: 'O Novo Testamento tem 27 livros: 4 Evangelhos, Atos, 13 cartas paulinas, Hebreus, 7 cartas católicas e Apocalipse. A lista exata aparece na carta de Santo Atanásio (367) e nos sínodos de Hipona (393) e Cartago (397).', whyEn: 'The New Testament has 27 books: 4 Gospels, Acts, 13 Pauline letters, Hebrews, 7 catholic letters and Revelation. The exact list appears in the letter of St. Athanasius (367) and at the synods of Hippo (393) and Carthage (397).' },
  { id: 'dq-005', question: 'Qual apóstolo negou Jesus três vezes antes do galo cantar?', questionEn: 'Which apostle denied Jesus three times before the rooster crowed?', options: ['Judas', 'Tomé', 'Pedro', 'João'], optionsEn: ['Judas', 'Thomas', 'Peter', 'John'], correct: 2, why: 'Pedro negou Jesus três vezes no pátio do sumo sacerdote (Lc 22,54-62). O galo cantou e Pedro "saiu e chorou amargamente". Depois da Ressurreição, Jesus o restaurou três vezes (Jo 21,15-17).', whyEn: 'Peter denied Jesus three times in the courtyard of the high priest (Lk 22:54-62). The rooster crowed and Peter "went out and wept bitterly". After the Resurrection, Jesus restored him three times (Jn 21:15-17).' },
  { id: 'dq-006', question: 'Quantos apóstolos escolheu Jesus?', questionEn: 'How many apostles did Jesus choose?', options: ['7', '10', '12', '70'], optionsEn: ['7', '10', '12', '70'], correct: 2, why: 'Jesus escolheu doze apóstolos (Mc 3,14-19), em correspondência com as doze tribos de Israel. O número 12 simboliza a fundação do novo povo de Deus.', whyEn: 'Jesus chose twelve apostles (Mk 3:14-19), corresponding to the twelve tribes of Israel. The number 12 symbolizes the foundation of the new people of God.' },
  { id: 'dq-007', question: 'Qual versículo costuma ser citado como o mais curto da Bíblia?', questionEn: 'Which verse is commonly cited as the shortest in the Bible?', options: ['1 João 4,8 ("Deus é amor")', 'João 11,35 ("Jesus chorou")', 'João 1,1 ("No princípio era o Verbo")', '1 Tessalonicenses 5,17 ("Orai sem cessar")'], optionsEn: ['1 John 4:8 ("God is love")', 'John 11:35 ("Jesus wept")', 'John 1:1 ("In the beginning was the Word")', '1 Thessalonians 5:17 ("Pray without ceasing")'], correct: 1, why: 'Em traduções como a de Almeida ("Jesus chorou") e a King James ("Jesus wept"), João 11,35 é o versículo mais curto. A Bíblia Ave Maria traz "Jesus pôs-se a chorar", e no grego o mais curto é 1 Tessalonicenses 5,16. O choro de Jesus diante do túmulo de Lázaro mostra sua humanidade e compaixão.', whyEn: 'In translations such as the King James ("Jesus wept"), John 11:35 is the shortest verse; in the Greek original the shortest is 1 Thessalonians 5:16. Jesus weeping before the tomb of Lazarus shows his humanity and compassion.' },
  { id: 'dq-008', question: 'Qual é o primeiro livro da Bíblia?', questionEn: 'What is the first book of the Bible?', options: ['Êxodo', 'Salmos', 'Gênesis', 'Mateus'], optionsEn: ['Exodus', 'Psalms', 'Genesis', 'Matthew'], correct: 2, why: '"No princípio, Deus criou o céu e a terra" (Gn 1,1). O Gênesis narra a criação, a queda, Noé, Abraão, Isaac, Jacó e José: as origens da história da salvação.', whyEn: '"In the beginning God created heaven, and earth" (Gn 1:1). Genesis recounts creation, the fall, Noah, Abraham, Isaac, Jacob and Joseph: the origins of salvation history.' },
  { id: 'dq-009', question: 'Em que cidade nasceu Jesus?', questionEn: 'In what city was Jesus born?', options: ['Nazaré', 'Jerusalém', 'Belém', 'Cafarnaum'], optionsEn: ['Nazareth', 'Jerusalem', 'Bethlehem', 'Capernaum'], correct: 2, why: 'Jesus nasceu em Belém da Judeia (Mt 2,1; Lc 2,4-7), como anunciava Miqueias 5,1. Cresceu em Nazaré, por isso era chamado "o Nazareno".', whyEn: 'Jesus was born in Bethlehem of Judea (Mt 2:1; Lk 2:4-7), as Micah 5:2 foretold (5:1 in some Bibles). He grew up in Nazareth, which is why he was called "the Nazarene".' },
  { id: 'dq-010', question: 'Quem batizou Jesus?', questionEn: 'Who baptized Jesus?', options: ['Pedro', 'João Batista', 'Um anjo', 'José'], optionsEn: ['Peter', 'John the Baptist', 'An angel', 'Joseph'], correct: 1, why: 'João Batista batizou Jesus no rio Jordão (Mt 3,13-17). João hesitou, dizendo precisar ser batizado por Jesus. Ao ser batizado, o Espírito desceu como pomba e o Pai disse: "Este é o meu Filho amado".', whyEn: 'John the Baptist baptized Jesus in the Jordan River (Mt 3:13-17). John hesitated, saying he needed to be baptized by Jesus. At the baptism, the Spirit descended as a dove and the Father said: "This is my beloved Son".' },
  { id: 'dq-011', question: 'Qual o significado do nome "Jesus" em hebraico?', questionEn: 'What is the meaning of the name "Jesus" in Hebrew?', options: ['Luz do mundo', 'Filho de Deus', 'Deus salva', 'Rei dos reis'], optionsEn: ['Light of the world', 'Son of God', 'God saves', 'King of kings'], correct: 2, why: '"Jesus" vem do hebraico Yehoshua, ou Yeshua, "o Senhor salva". O anjo disse a José: "porás o nome de Jesus, porque ele salvará o seu povo de seus pecados" (Mt 1,21).', whyEn: '"Jesus" comes from the Hebrew Yehoshua, or Yeshua, "the Lord saves". The angel told Joseph: "thou shalt call his name Jesus. For he shall save his people from their sins" (Mt 1:21).' },
  { id: 'dq-012', question: 'Quantos dias ficou Jesus no deserto tentado pelo diabo?', questionEn: 'How many days did Jesus spend in the desert being tempted by the devil?', options: ['3 dias', '7 dias', '30 dias', '40 dias'], optionsEn: ['3 days', '7 days', '30 days', '40 days'], correct: 3, why: '40 dias (Mt 4,2; Lc 4,2), em paralelo com os 40 anos de Israel no deserto e os 40 dias de Moisés no Sinai. O número 40 na Bíblia indica período de provação e purificação.', whyEn: '40 days (Mt 4:2; Lk 4:2), in parallel with Israel\'s 40 years in the desert and Moses\'s 40 days on Sinai. The number 40 in the Bible indicates a period of trial and purification.' },
  { id: 'dq-013', question: 'Qual foi o primeiro milagre de Jesus registrado no Evangelho de João?', questionEn: 'What was Jesus\'s first miracle recorded in the Gospel of John?', options: ['Curar um cego', 'Multiplicar pães', 'Transformar água em vinho', 'Ressuscitar Lázaro'], optionsEn: ['Healing a blind man', 'Multiplying loaves', 'Turning water into wine', 'Raising Lazarus'], correct: 2, why: 'João 2,1-11: nas bodas de Caná, a pedido de Maria, Jesus transformou água em vinho. "Esse foi o primeiro milagre de Jesus", diz o evangelista, e com ele Jesus "manifestou a sua glória".', whyEn: 'John 2:1-11: at the wedding in Cana, at Mary\'s request, Jesus turned water into wine. "This beginning of miracles did Jesus", says the evangelist, and with it he "manifested his glory".' },
  { id: 'dq-014', question: 'Qual apóstolo traiu Jesus por trinta moedas de prata?', questionEn: 'Which apostle betrayed Jesus for thirty pieces of silver?', options: ['Simão Zelote', 'Tomé', 'Judas Iscariotes', 'Bartolomeu'], optionsEn: ['Simon the Zealot', 'Thomas', 'Judas Iscariot', 'Bartholomew'], correct: 2, why: 'Judas Iscariotes combinou com os chefes dos sacerdotes entregar Jesus por trinta moedas de prata (Mt 26,14-16), quantia que lembra Zacarias 11,12. Depois, tomado de remorsos, devolveu o dinheiro e se enforcou (Mt 27,3-5).', whyEn: 'Judas Iscariot arranged with the chief priests to hand Jesus over for thirty pieces of silver (Mt 26:14-16), a sum that recalls Zechariah 11:12. Later, seized with remorse, he returned the money and hanged himself (Mt 27:3-5).' },
  { id: 'dq-015', question: 'Em qual dia da semana Jesus ressuscitou?', questionEn: 'On which day of the week did Jesus rise?', options: ['Sexta-feira', 'Sábado', 'Domingo', 'Segunda-feira'], optionsEn: ['Friday', 'Saturday', 'Sunday', 'Monday'], correct: 2, why: 'Jesus ressuscitou "no primeiro dia que se seguia ao sábado" (Jo 20,1; Mc 16,2), o domingo. Por isso os cristãos celebram a Eucaristia aos domingos, o "Dia do Senhor" (Ap 1,10).', whyEn: 'Jesus rose "on the first day of the week" (Jn 20:1; Mk 16:2), Sunday. This is why Christians celebrate the Eucharist on Sundays, "the Lord\'s Day" (Rev 1:10).' },
  { id: 'dq-016', question: 'Quantos dias após a Ressurreição ocorreu a Ascensão de Jesus?', questionEn: 'How many days after the Resurrection did the Ascension of Jesus occur?', options: ['3 dias', '7 dias', '40 dias', '50 dias'], optionsEn: ['3 days', '7 days', '40 days', '50 days'], correct: 2, why: 'Atos 1,3: Jesus se mostrou aos apóstolos durante 40 dias depois da Ressurreição, falando do Reino de Deus. Depois subiu ao céu diante deles, no monte das Oliveiras (At 1,9-12).', whyEn: 'Acts 1:3: Jesus showed himself to the apostles for 40 days after the Resurrection, speaking of the kingdom of God. Then he ascended into heaven before them, on the Mount of Olives (Acts 1:9-12).' },
  { id: 'dq-017', question: 'Quantos dias após a Ascensão ocorreu Pentecostes?', questionEn: 'How many days after the Ascension did Pentecost occur?', options: ['3 dias', '7 dias', '10 dias', '40 dias'], optionsEn: ['3 days', '7 days', '10 days', '40 days'], correct: 2, why: 'Pentecostes vem do grego "quinquagésimo" (dia): é celebrado 50 dias depois da Páscoa e, portanto, 10 dias depois da Ascensão. O Espírito Santo desceu sobre os discípulos reunidos em Jerusalém (At 2,1-4), com os quais estava Maria (At 1,14).', whyEn: 'Pentecost comes from the Greek for "fiftieth" (day): it is celebrated 50 days after Easter and therefore 10 days after the Ascension. The Holy Spirit came down upon the disciples gathered in Jerusalem (Acts 2:1-4), with whom Mary was present (Acts 1:14).' },
  { id: 'dq-018', question: 'A tradição identifica o "discípulo amado" do Evangelho de João com qual apóstolo?', questionEn: 'Tradition identifies the "beloved disciple" of John\'s Gospel with which apostle?', options: ['Pedro', 'Paulo', 'João', 'Tiago'], optionsEn: ['Peter', 'Paul', 'John', 'James'], correct: 2, why: 'O "discípulo que Jesus amava" aparece em João 13, 19, 20 e 21, sem nome. A tradição, desde Santo Ireneu, o identifica com João, filho de Zebedeu. É o único dos Doze que o Evangelho mostra junto à Cruz, onde recebeu Maria aos seus cuidados (Jo 19,26-27).', whyEn: 'The "disciple whom Jesus loved" appears in John 13, 19, 20 and 21, without a name. Tradition, since St. Irenaeus, identifies him with John, son of Zebedee. He is the only one of the Twelve the Gospel shows at the Cross, where he took Mary into his care (Jn 19:26-27).' },
  { id: 'dq-019', question: 'Qual é o maior mandamento, segundo Jesus?', questionEn: 'What is the greatest commandment, according to Jesus?', options: ['Não matarás', 'Amar a Deus com todo o coração, alma e mente', 'Guardar o sábado', 'Não cobiçarás'], optionsEn: ['You shall not kill', 'Love God with all your heart, soul, and mind', 'Keep the Sabbath', 'You shall not covet'], correct: 1, why: 'Mateus 22,37-40: Jesus cita Deuteronômio 6,5 como o maior mandamento e acrescenta o segundo, "amarás teu próximo como a ti mesmo" (Lv 19,18). "Nesses dois mandamentos se resumem toda a Lei e os Profetas."', whyEn: 'Matthew 22:37-39: Jesus quotes Deuteronomy 6:5 as the greatest commandment, and adds the second (Lv 19:18): "you shall love your neighbor as yourself". "On these two commandments hang all the Law and the Prophets."' },
  { id: 'dq-020', question: 'Qual é o fruto mais importante do Espírito Santo, segundo São Paulo?', questionEn: 'What is the greatest fruit of the Holy Spirit, according to St. Paul?', options: ['Alegria', 'Paz', 'Amor', 'Paciência'], optionsEn: ['Joy', 'Peace', 'Love', 'Patience'], correct: 2, why: 'Gálatas 5,22 abre a lista dos frutos do Espírito com a caridade (o amor), e 1 Coríntios 13,13 diz: "a maior delas é a caridade". Paulo insiste: "Ainda que eu falasse as línguas dos homens e dos anjos, se não tiver caridade, sou como o bronze que soa" (1 Cor 13,1).', whyEn: 'Galatians 5:22 opens the list of the fruits of the Spirit with charity (love), and 1 Corinthians 13:13 says: "the greatest of these is charity". Paul insists: "If I speak with the tongues of men and of angels, and have not charity, I am become as sounding brass" (1 Cor 13:1).' },
  { id: 'dq-021', question: 'Quantas Bem-Aventuranças Jesus proclamou no Sermão da Montanha?', questionEn: 'How many Beatitudes did Jesus proclaim in the Sermon on the Mount?', options: ['5', '7', '8', '10'], optionsEn: ['5', '7', '8', '10'], correct: 2, why: 'Mateus 5,3-10 lista 8 Bem-Aventuranças, cada uma começando com "Bem-aventurados os...". Lucas 6,20-23 registra 4. As oito de Mateus são o texto clássico da tradição cristã.', whyEn: 'Matthew 5:3-10 lists 8 Beatitudes, each beginning "Blessed are the...". Luke 6:20-23 records 4. Matthew\'s eight are the classical text in Christian tradition.' },
  { id: 'dq-022', question: 'O que é a "graça santificante"?', questionEn: 'What is "sanctifying grace"?', options: ['Um sentimento de paz interior', 'A participação na vida divina que nos torna agradáveis a Deus e filhos Seus', 'A capacidade de fazer milagres', 'O perdão dos pecados veniais'], optionsEn: ['A feeling of inner peace', 'Participation in divine life that makes us pleasing to God and His children', 'The ability to work miracles', 'The forgiveness of venial sins'], correct: 1, why: 'O Catecismo (§2000) define a graça santificante como "um dom habitual, uma disposição estável e sobrenatural, que aperfeiçoa a alma" para torná-la capaz de viver com Deus. Ela nos faz "participantes da natureza divina" (2 Pd 1,4). Perde-se pelo pecado mortal e é restituída pela Confissão.', whyEn: 'The Catechism (§2000) defines sanctifying grace as "an habitual gift, a stable and supernatural disposition that perfects the soul itself to enable it to live with God". It makes us "partakers of the divine nature" (2 Pt 1:4). It is lost through mortal sin and restored through Confession.' },
  { id: 'dq-023', question: 'Qual é a única petição do Pai-Nosso que Jesus comentou explicitamente?', questionEn: 'Which is the only petition of the Our Father that Jesus explicitly commented on?', options: ['O pão nosso de cada dia', 'O perdão das ofensas', 'A libertação do mal', 'A vinda do Reino'], optionsEn: ['Our daily bread', 'Forgiveness of offenses', 'Deliverance from evil', 'The coming of the Kingdom'], correct: 1, why: 'Depois do Pai-Nosso, Jesus comenta só esta petição: "Porque, se perdoardes aos homens as suas ofensas, vosso Pai celeste também vos perdoará. Mas, se não perdoardes aos homens, tampouco vosso Pai vos perdoará" (Mt 6,14-15).', whyEn: 'After the Our Father, Jesus comments only: "For if you forgive others their trespasses, your heavenly Father will also forgive you; but if you do not forgive others, neither will your Father forgive your trespasses" (Mt 6:14-15).' },
  { id: 'dq-024', question: 'Qual livro da Bíblia tem mais capítulos?', questionEn: 'Which book of the Bible has the most chapters?', options: ['Gênesis', 'Isaías', 'Salmos', 'Jeremias'], optionsEn: ['Genesis', 'Isaiah', 'Psalms', 'Jeremiah'], correct: 2, why: 'O livro dos Salmos tem 150 salmos e é também o que tem mais versículos. Em número de palavras do texto hebraico, Jeremias é um pouco maior. Os Salmos estão entre os livros mais citados no Novo Testamento, e Jesus rezou um deles na Cruz (Sl 22, que é o 21 na numeração da Bíblia Ave Maria).', whyEn: 'The Book of Psalms has 150 psalms and also has the most verses. In number of words of the Hebrew text, Jeremiah is slightly longer. The Psalms are among the books most quoted in the New Testament, and Jesus prayed one of them on the Cross (Ps 22, numbered 21 in the Douay-Rheims).' },
  { id: 'dq-025', question: 'O que era São Paulo antes de se converter?', questionEn: 'What was St. Paul before his conversion?', options: ['Pescador', 'Carpinteiro', 'Fariseu e perseguidor dos cristãos', 'Publicano'], optionsEn: ['Fisherman', 'Carpenter', 'Pharisee and persecutor of Christians', 'Tax collector'], correct: 2, why: 'Paulo (Saulo de Tarso) era fariseu, formado por Gamaliel (At 22,3; Fl 3,5), e perseguia os cristãos: aprovou a morte de Estêvão (At 7,58; 8,1). Converteu-se no caminho de Damasco (At 9). Por ofício, fabricava tendas (At 18,3).', whyEn: 'Paul (Saul of Tarsus) was a Pharisee, trained under Gamaliel (Acts 22:3; Phil 3:5), and persecuted Christians: he approved of Stephen\'s death (Acts 7:58; 8:1). He was converted on the road to Damascus (Acts 9). By trade, he was a tentmaker (Acts 18:3).' },
  { id: 'dq-026', question: 'Qual saudação o anjo Gabriel usou ao aparecer a Maria?', questionEn: 'What greeting did the angel Gabriel use when appearing to Mary?', options: ['Shalom, Maria', 'Ave, cheia de graça', 'Louvado seja o Senhor', 'Paz a ti'], optionsEn: ['Shalom, Mary', 'Hail, full of grace', 'Praise be to the Lord', 'Peace to you'], correct: 1, why: 'Lucas 1,28: "Ave, cheia de graça, o Senhor é contigo". O grego kecharitoméne (particípio perfeito passivo) indica alguém que foi e permanece repleta da graça de Deus. É um dos textos que a Igreja lê em favor da Imaculada Conceição (Catecismo §490-491).', whyEn: 'Luke 1:28: "Hail, full of grace, the Lord is with thee". The Greek kecharitomene (perfect passive participle) indicates someone who has been and remains filled with God\'s grace. It is one of the texts the Church reads in support of the Immaculate Conception (Catechism §490-491).' },
  { id: 'dq-027', question: 'Como Isabel chamou Jesus, ainda no ventre de Maria?', questionEn: 'What did Elizabeth call Jesus, while he was still in Mary\'s womb?', options: ['Messias', 'Senhor', 'Emanuel', 'Filho do Altíssimo'], optionsEn: ['Messiah', 'Lord', 'Emmanuel', 'Son of the Most High'], correct: 1, why: 'Quando Maria a visitou, a criança (João) estremeceu no seio de Isabel, e ela exclamou: "Donde me vem esta honra de vir a mim a mãe de meu Senhor?" (Lc 1,43). Isabel, cheia do Espírito Santo, reconhece em Jesus o "Senhor".', whyEn: 'When Mary visited her, the child (John) leaped in Elizabeth\'s womb, and she exclaimed: "whence is this to me that the mother of my Lord should come to me?" (Lk 1:43). Elizabeth, filled with the Holy Spirit, recognizes Jesus as "Lord".' },
  { id: 'dq-028', question: 'Qual destes sacramentos imprime caráter indelével e por isso não pode ser repetido?', questionEn: 'Which of these sacraments imprints an indelible character and therefore cannot be repeated?', options: ['Eucaristia', 'Confissão', 'Batismo', 'Matrimônio'], optionsEn: ['Eucharist', 'Confession', 'Baptism', 'Matrimony'], correct: 2, why: 'Três sacramentos imprimem caráter: Batismo, Confirmação e Ordem, e por isso não se repetem (Catecismo §1121; Código de Direito Canônico, cân. 845). O Catecismo (§1272) diz que o Batismo marca o cristão com um "selo espiritual indelével". Entre as alternativas, só o Batismo está nesse grupo.', whyEn: 'Three sacraments imprint a character: Baptism, Confirmation and Holy Orders, and so they are not repeated (Catechism §1121; Code of Canon Law, can. 845). The Catechism (§1272) says that Baptism seals the Christian with an "indelible spiritual mark". Among the options, only Baptism belongs to this group.' },
  { id: 'dq-029', question: 'Qual oração é repetida mais vezes no terço do Rosário?', questionEn: 'Which prayer is repeated most often in praying the Rosary?', options: ['Pai-Nosso', 'Ave Maria', 'Credo', 'Salve Regina'], optionsEn: ['Our Father', 'Hail Mary', 'Creed', 'Hail Holy Queen'], correct: 1, why: 'Cada mistério tem um Pai-Nosso, dez Ave-Marias e um Glória, então o terço tem pelo menos 50 Ave-Marias. A oração une a saudação do anjo (Lc 1,28), a de Isabel (Lc 1,42) e uma súplica que se firmou no fim da Idade Média e entrou no Breviário de São Pio V (1568).', whyEn: 'Each mystery has one Our Father, ten Hail Marys and one Glory Be, so each set of five mysteries has at least 50 Hail Marys. The prayer joins the angel\'s greeting (Lk 1:28), Elizabeth\'s (Lk 1:42) and a petition that took shape in the late Middle Ages and entered the Breviary of St. Pius V (1568).' },
  { id: 'dq-030', question: 'O que significa "Amen" ao final das orações?', questionEn: 'What does "Amen" at the end of prayers mean?', options: ['Obrigado', 'Fim da oração', 'Assim seja / Verdadeiramente', 'Louvor a Deus'], optionsEn: ['Thank you', 'End of prayer', 'So be it / Truly', 'Praise to God'], correct: 2, why: '"Amém" vem do hebraico "amen" (firme, verdadeiro). Na Bíblia indica ratificação e confiança. Jesus usava "Amém, amém, digo-vos" (em João) para marcar declarações solenes. No final das orações, expressa acordo e confiança.', whyEn: '"Amen" comes from the Hebrew "amen" (firm, true). In the Bible it indicates ratification and trust. Jesus used "Amen, amen, I say to you" (in John) to mark solemn declarations. At the end of prayers it expresses agreement and trust.' },
  { id: 'dq-031', question: 'Quais são as três virtudes teologais?', questionEn: 'What are the three theological virtues?', options: ['Fé, esperança e caridade', 'Prudência, justiça e fortaleza', 'Humildade, obediência e pobreza', 'Oração, jejum e esmola'], optionsEn: ['Faith, hope, and charity', 'Prudence, justice, and fortitude', 'Humility, obedience, and poverty', 'Prayer, fasting, and almsgiving'], correct: 0, why: '1 Coríntios 13,13: "Por ora subsistem a fé, a esperança e a caridade, as três. Porém, a maior delas é a caridade". São chamadas "teologais" porque têm Deus como origem, motivo e objeto (Catecismo §1812).', whyEn: '1 Corinthians 13:13: "And now there remain faith, hope, and charity, these three: but the greatest of these is charity". They are called "theological" because God is their origin, motive and object (Catechism §1812).' },
  { id: 'dq-032', question: 'Quais são as quatro virtudes cardeais?', questionEn: 'What are the four cardinal virtues?', options: ['Fé, esperança, caridade e paciência', 'Prudência, justiça, fortaleza e temperança', 'Humildade, obediência, castidade e pobreza', 'Oração, jejum, esmola e penitência'], optionsEn: ['Faith, hope, charity, and patience', 'Prudence, justice, fortitude, and temperance', 'Humility, obedience, chastity, and poverty', 'Prayer, fasting, almsgiving, and penance'], correct: 1, why: 'As quatro virtudes cardeais aparecem em Platão e em Sabedoria 8,7, e foram desenvolvidas por Santo Ambrósio, Santo Agostinho e Tomás de Aquino (Catecismo §1805). "Cardeal" vem do latim cardo, dobradiça: as outras virtudes giram em torno delas.', whyEn: 'The four cardinal virtues appear in Plato and in Wisdom 8:7, and were developed by St. Ambrose, St. Augustine and Thomas Aquinas (Catechism §1805). "Cardinal" comes from the Latin cardo, hinge: the other virtues turn on them.' },
  { id: 'dq-033', question: 'Quais são os sete pecados capitais?', questionEn: 'What are the seven capital sins?', options: ['Orgulho, inveja, ira, avareza, preguiça, gula, luxúria', 'Mentira, roubo, assassinato, adultério, idolatria, blasfêmia, desobediência', 'Heresia, apostasia, cisma, sacrilégio, impiedade, superstição, magia', 'Soberba, acídia, timidez, fraqueza, indiferença, medo, desconfiança'], optionsEn: ['Pride, envy, anger, greed, sloth, gluttony, lust', 'Lying, theft, murder, adultery, idolatry, blasphemy, disobedience', 'Heresy, apostasy, schism, sacrilege, impiety, superstition, magic', 'Pride, acedia, timidity, weakness, indifference, fear, distrust'], correct: 0, why: 'Os sete pecados capitais (São Gregório Magno, séc. VI) são raízes de outros pecados: soberba, avareza, inveja, ira, luxúria, gula e preguiça ou acídia (Catecismo §1866). "Capital" vem de caput, cabeça: são a fonte de outros.', whyEn: 'The seven capital sins (St. Gregory the Great, 6th century) are roots of other sins: pride, avarice, envy, wrath, lust, gluttony and sloth or acedia (Catechism §1866). "Capital" comes from caput, head: they are the source of others.' },
  { id: 'dq-034', question: 'Quem escreveu o livro dos Atos dos Apóstolos?', questionEn: 'Who wrote the Book of Acts?', options: ['Pedro', 'Paulo', 'Lucas', 'João'], optionsEn: ['Peter', 'Paul', 'Luke', 'John'], correct: 2, why: 'Atos foi escrito pelo mesmo autor do Terceiro Evangelho, e os dois livros formam uma obra em dois volumes dedicada a Teófilo (Lc 1,3; At 1,1). Desde Santo Ireneu (por volta de 180), a tradição identifica o autor com Lucas, médico e companheiro de Paulo (Cl 4,14).', whyEn: 'Acts was written by the same author as the Third Gospel, and the two books form a two-volume work dedicated to Theophilus (Lk 1:3; Acts 1:1). Since St. Irenaeus (around 180), tradition has identified the author with Luke, physician and companion of Paul (Col 4:14).' },
  { id: 'dq-035', question: 'O que é a "lectio divina"?', questionEn: 'What is "lectio divina"?', options: ['A leitura do cânon litúrgico pelo padre', 'Uma prática de leitura orante da Escritura em quatro etapas', 'O estudo crítico histórico da Bíblia', 'A recitação do breviário'], optionsEn: ['The liturgical canon reading by the priest', 'A prayerful reading of Scripture in four steps', 'The historical-critical study of the Bible', 'The recitation of the Breviary'], correct: 1, why: 'A lectio divina (leitura divina) é uma prática monástica, descrita por Guigo II, o Cartuxo (séc. XII), em quatro degraus: lectio (ler), meditatio (meditar), oratio (orar) e contemplatio (contemplar). Bento XVI a recomendou a todos os fiéis na Verbum Domini (2010, n. 86-87).', whyEn: 'Lectio divina (divine reading) is a monastic practice, described by Guigo II the Carthusian (12th century) in four steps: lectio (reading), meditatio (meditation), oratio (prayer) and contemplatio (contemplation). Benedict XVI recommended it to all the faithful in Verbum Domini (2010, no. 86-87).' },
  { id: 'dq-036', question: 'No rito latino, qual destes sacramentos tem só o bispo como ministro ordinário?', questionEn: 'In the Latin rite, which of these sacraments has only the bishop as its ordinary minister?', options: ['Batismo', 'Eucaristia', 'Confirmação', 'Matrimônio'], optionsEn: ['Baptism', 'Eucharist', 'Confirmation', 'Matrimony'], correct: 2, why: 'No rito latino, o ministro ordinário da Confirmação é o bispo (Catecismo §1313; Código de Direito Canônico, cân. 882). Um presbítero pode confirmar se tiver essa faculdade pelo direito, por exemplo ao batizar um adulto ou em perigo de morte, ou por concessão do bispo. Nas Igrejas orientais, o presbítero que batiza crisma logo em seguida.', whyEn: 'In the Latin rite, the ordinary minister of Confirmation is the bishop (Catechism §1313; Code of Canon Law, can. 882). A presbyter may confirm if he has this faculty by law, for example when baptizing an adult or in danger of death, or by grant of the bishop. In the Eastern Churches, the priest who baptizes confirms immediately afterwards.' },
  { id: 'dq-037', question: 'Qual é o livro do Antigo Testamento que narra a história de Rute?', questionEn: 'Which Old Testament book tells the story of Ruth?', options: ['Juízes', 'Rute', 'Ester', 'Tobias'], optionsEn: ['Judges', 'Ruth', 'Esther', 'Tobit'], correct: 1, why: 'O Livro de Rute narra a fidelidade de Rute, moabita, à sogra Noemi: "Aonde fores, eu irei; onde habitares, eu habitarei" (Rt 1,16). Rute é antepassada de Davi e de Jesus (Rt 4,17; Mt 1,5).', whyEn: 'The Book of Ruth recounts the faithfulness of Ruth, a Moabite, to her mother-in-law Naomi: "whithersoever thou shalt go, I will go: and where thou shalt dwell, I also will dwell" (Ru 1:16). Ruth is an ancestor of David and of Jesus (Ru 4:17; Mt 1:5).' },
  { id: 'dq-038', question: 'Quem escreveu a maioria das cartas do Novo Testamento?', questionEn: 'Who wrote most of the letters in the New Testament?', options: ['Pedro', 'João', 'Paulo', 'Tiago'], optionsEn: ['Peter', 'John', 'Paul', 'James'], correct: 2, why: 'Treze cartas do Novo Testamento levam o nome de Paulo, de Romanos a Filêmon, e a tradição antiga somava ainda Hebreus. São quase metade dos 27 livros. Mesmo os estudiosos que discutem a autoria de algumas aceitam sete como certamente dele.', whyEn: 'Thirteen New Testament letters bear Paul\'s name, from Romans to Philemon, and ancient tradition added Hebrews. They make up almost half of the 27 books. Even scholars who question the authorship of some accept seven as certainly his.' },
  { id: 'dq-039', question: 'O que celebra a Festa de Corpus Christi?', questionEn: 'What does the Feast of Corpus Christi celebrate?', options: ['A Ressurreição de Cristo', 'A instituição da Eucaristia e a presença real de Cristo no sacramento', 'O Batismo de Jesus', 'A Ascensão ao Céu'], optionsEn: ['The Resurrection of Christ', 'The institution of the Eucharist and the real presence of Christ in the sacrament', 'The Baptism of Jesus', 'The Ascension to Heaven'], correct: 1, why: 'A festa de Corpus Christi (Corpo de Cristo) foi estendida a toda a Igreja pelo Papa Urbano IV em 1264. Celebra a presença real de Jesus na Eucaristia, com procissão, adoração e os textos atribuídos a São Tomás de Aquino, como o Pange lingua, cujas duas últimas estrofes formam o Tantum ergo.', whyEn: 'The feast of Corpus Christi (Body of Christ) was extended to the whole Church by Pope Urban IV in 1264. It celebrates the real presence of Jesus in the Eucharist, with procession, adoration and the texts attributed to St. Thomas Aquinas, such as the Pange lingua, whose last two stanzas form the Tantum ergo.' },
  { id: 'dq-040', question: 'Qual é a promessa central do Evangelho (kerygma)?', questionEn: 'What is the central promise of the Gospel (kerygma)?', options: ['Prosperidade material para os crentes', 'Salvação e vida eterna pela fé em Jesus Cristo morto e ressuscitado', 'Paz política entre as nações', 'Saúde perfeita e ausência de sofrimento'], optionsEn: ['Material prosperity for believers', 'Salvation and eternal life through faith in Jesus Christ, dead and risen', 'Political peace between nations', 'Perfect health and absence of suffering'], correct: 1, why: 'O kerygma primitivo (At 2,22-36; 1 Cor 15,3-5): Jesus morreu pelos nossos pecados, foi sepultado, ressuscitou ao terceiro dia e apareceu. Quem crê e se batiza é salvo (Mc 16,16).', whyEn: 'The primitive kerygma (Acts 2:22-36; 1 Cor 15:3-5): Jesus died for our sins, was buried, rose on the third day, and appeared. Whoever believes and is baptized will be saved (Mk 16:16).' },
  { id: 'dq-041', question: 'O que é o "Fiat" de Maria?', questionEn: 'What is Mary\'s "Fiat"?', options: ['O nome de seu pai', 'Seu consentimento à Encarnação: "Faça-se em mim segundo a tua palavra"', 'Uma oração de intercessão', 'Sua saudação a Isabel'], optionsEn: ['The name of her father', 'Her consent to the Incarnation: "Be it done to me according to your word"', 'A prayer of intercession', 'Her greeting to Elizabeth'], correct: 1, why: 'Lucas 1,38: "Eis aqui a serva do Senhor. Faça-se em mim segundo a tua palavra". O "Fiat" (faça-se) de Maria é o sim que acolhe a Encarnação. Santo Ireneu já o contrapunha à desobediência de Eva.', whyEn: 'Luke 1:38: "Behold the handmaid of the Lord: be it done to me according to thy word". Mary\'s "Fiat" (let it be done) is the yes that welcomes the Incarnation. St. Irenaeus already contrasted it with Eve\'s disobedience.' },
  { id: 'dq-042', question: 'O que celebra o Domingo de Ramos?', questionEn: 'What does Palm Sunday celebrate?', options: ['A Última Ceia de Jesus', 'A entrada triunfal de Jesus em Jerusalém', 'A Ressurreição de Jesus', 'O Batismo de Jesus'], optionsEn: ['The Last Supper of Jesus', 'The triumphal entry of Jesus into Jerusalem', 'The Resurrection of Jesus', 'The Baptism of Jesus'], correct: 1, why: 'O Domingo de Ramos abre a Semana Santa. Jesus entrou em Jerusalém montado num jumento, cumprindo Zacarias 9,9. A multidão o aclamava com ramos e "Hosana ao Filho de Davi" (Mt 21,9).', whyEn: 'Palm Sunday opens Holy Week. Jesus entered Jerusalem riding a donkey, fulfilling Zechariah 9:9. The crowd hailed him with branches and "Hosanna to the Son of David" (Mt 21:9).' },
  { id: 'dq-043', question: 'Quem foi o primeiro mártir (protomártir) do cristianismo?', questionEn: 'Who was the first martyr (protomartyr) of Christianity?', options: ['São João Batista', 'São Estêvão', 'São Pedro', 'São Paulo'], optionsEn: ['St. John the Baptist', 'St. Stephen', 'St. Peter', 'St. Paul'], correct: 1, why: 'Estêvão, um dos sete escolhidos para servir a comunidade (At 6), foi levado ao Sinédrio e apedrejado (At 7). É o primeiro mártir cristão. Suas últimas palavras: "Senhor Jesus, recebe o meu espírito... Senhor, não lhes leves em conta este pecado" (At 7,59-60). João Batista morreu antes, mas é contado como o último profeta da Antiga Aliança.', whyEn: 'Stephen, one of the seven chosen to serve the community (Acts 6), was brought before the Sanhedrin and stoned (Acts 7). He is the first Christian martyr. His last words: "Lord Jesus, receive my spirit... Lord, lay not this sin to their charge" (Acts 7:59-60). John the Baptist died earlier, but is counted as the last prophet of the Old Covenant.' },
  { id: 'dq-044', question: 'Qual é o pecado que Jesus disse não ter perdão?', questionEn: 'What is the sin that Jesus said has no forgiveness?', options: ['Assassinato', 'Adultério', 'Blasfêmia contra o Espírito Santo', 'Apostasia'], optionsEn: ['Murder', 'Adultery', 'Blasphemy against the Holy Spirit', 'Apostasy'], correct: 2, why: 'Mateus 12,31-32: "todo pecado e toda blasfêmia serão perdoados aos homens, mas a blasfêmia contra o Espírito não lhes será perdoada". O Catecismo (§1864) explica que é a recusa deliberada de acolher a misericórdia de Deus pelo arrependimento.', whyEn: 'Matthew 12:31-32: "Every sin and blasphemy shall be forgiven men, but the blasphemy of the Spirit shall not be forgiven". The Catechism (§1864) explains that it is the deliberate refusal to accept God\'s mercy by repenting.' },
  { id: 'dq-045', question: 'O que é a "Tradição Apostólica"?', questionEn: 'What is the "Apostolic Tradition"?', options: ['Os escritos dos Padres da Igreja', 'O ensinamento transmitido pelos apóstolos, vivo na Igreja, distinto mas não separado da Escritura', 'As regras de disciplina eclesiástica', 'Os costumes litúrgicos medievais'], optionsEn: ['The writings of the Church Fathers', 'The teaching transmitted by the apostles, alive in the Church, distinct but not separate from Scripture', 'The rules of ecclesiastical discipline', 'Medieval liturgical customs'], correct: 1, why: 'A Dei Verbum (n. 10) ensina que "a sagrada Tradição e a Sagrada Escritura constituem um só depósito sagrado da palavra de Deus, confiado à Igreja". Paulo manda guardar o que foi ensinado "seja por palavras, seja por carta" (2 Ts 2,15).', whyEn: 'Dei Verbum (no. 10) teaches that "sacred tradition and Sacred Scripture form one sacred deposit of the word of God, committed to the Church". Paul commands keeping what was taught "whether by word, or by our epistle" (2 Th 2:15).' },
  { id: 'dq-046', question: 'Qual profeta do Antigo Testamento anunciou: "uma virgem conceberá e dará à luz um filho"?', questionEn: 'Which Old Testament prophet foretold: "a virgin shall conceive, and bear a son"?', options: ['Jeremias', 'Ezequiel', 'Isaías', 'Miqueias'], optionsEn: ['Jeremiah', 'Ezekiel', 'Isaiah', 'Micah'], correct: 2, why: 'Isaías 7,14, citado em Mateus 1,23. O hebraico almah quer dizer "jovem" (moça em idade de casar), e a Septuaginta traduziu por parthénos, "virgem", forma que Mateus segue ao aplicar a profecia a Maria. O nome Emanuel quer dizer "Deus conosco".', whyEn: 'Isaiah 7:14, quoted in Matthew 1:23. The Hebrew almah means "young woman" (a girl of marriageable age), and the Septuagint rendered it parthenos, "virgin", the form Matthew follows in applying the prophecy to Mary. The name Emmanuel means "God with us".' },
  { id: 'dq-047', question: 'Qual é o significado de "Pentecostes" para os judeus antes de Cristo?', questionEn: 'What is the meaning of "Pentecost" for Jews before Christ?', options: ['Festa das Semanas: colheita do trigo, depois associada também à entrega da Lei no Sinai', 'Festa da Páscoa', 'Início do ano novo judaico', 'Dia do Grande Perdão'], optionsEn: ['Feast of Weeks: the wheat harvest, later also associated with the giving of the Law at Sinai', 'Passover feast', 'Start of the Jewish new year', 'Day of Great Forgiveness'], correct: 0, why: 'No Antigo Testamento, a festa das Semanas (Shavuot) celebrava as primícias do trigo, sete semanas depois da Páscoa (Lv 23,15-21; Dt 16,9-10). No judaísmo posterior, passou a lembrar também o dom da Lei no Sinai. Em Atos 2, o Espírito Santo é dado nessa festa, e os cristãos veem nisso a lei gravada no coração anunciada em Jeremias 31,33.', whyEn: 'In the Old Testament, the Feast of Weeks (Shavuot) celebrated the firstfruits of the wheat, seven weeks after Passover (Lv 23:15-21; Dt 16:9-10). In later Judaism it also came to commemorate the gift of the Law at Sinai. In Acts 2 the Holy Spirit is given at this feast, and Christians see in it the law written on the heart announced in Jeremiah 31:33.' },
  { id: 'dq-048', question: 'Qual é a definição clássica de oração dada por Santa Teresa de Ávila?', questionEn: 'What is the classical definition of prayer given by St. Teresa of Ávila?', options: ['Falar com Deus repetindo fórmulas sagradas', 'Conversa íntima de amizade com Aquele que sabemos que nos ama', 'A leitura atenta da Sagrada Escritura', 'O cumprimento dos ritos litúrgicos com devoção'], optionsEn: ['Speaking to God by repeating sacred formulas', 'Intimate friendly conversation with Him whom we know loves us', 'The attentive reading of Sacred Scripture', 'The fulfillment of liturgical rites with devotion'], correct: 1, why: 'Santa Teresa, no Livro da Vida (cap. 8), escreve: "Outra coisa não é, a meu parecer, oração mental, senão tratar de amizade, estando muitas vezes tratando a sós com Quem sabemos que nos ama". O Catecismo (§2709) cita essa definição.', whyEn: 'St. Teresa, in her Life (ch. 8), writes that mental prayer "is nothing else than a close sharing between friends; it means taking time frequently to be alone with him who we know loves us". The Catechism (§2709) quotes this definition.' },
  { id: 'dq-049', question: 'Qual salmo começa com as palavras "O Senhor é meu pastor"?', questionEn: 'Which psalm begins with the words "The Lord is my shepherd"?', options: ['Salmo 1', 'Salmo 23 (22)', 'Salmo 51 (50)', 'Salmo 150'], optionsEn: ['Psalm 1', 'Psalm 23 (22)', 'Psalm 51 (50)', 'Psalm 150'], correct: 2, why: 'É o Salmo 23 na numeração hebraica e 22 na grega e latina, usada pela Bíblia Ave Maria. Une intimidade ("nada me faltará") e confiança diante da morte ("ainda que eu atravesse o vale escuro, nada temerei").', whyEn: 'It is Psalm 23 in the Hebrew numbering and 22 in the Greek and Latin numbering used by the Douay-Rheims. It combines intimacy ("I shall want nothing") and trust in the face of death ("though I should walk in the midst of the shadow of death, I will fear no evils").' },
  { id: 'dq-050', question: 'O que é o "Magnificat"?', questionEn: 'What is the "Magnificat"?', options: ['Um decreto papal', 'O cântico de louvor de Maria ao visitar Isabel (Lc 1,46-55)', 'A oração de consagração da Missa', 'Um hino gregoriano medieval'], optionsEn: ['A papal decree', 'Mary\'s canticle of praise when visiting Elizabeth (Lk 1:46-55)', 'The prayer of consecration of the Mass', 'A medieval Gregorian hymn'], correct: 1, why: 'Lucas 1,46-55: "Minha alma glorifica o Senhor..." Maria celebra a misericórdia de Deus para com os humildes. O Magnificat é rezado diariamente nas Vésperas (Liturgia das Horas) da Igreja.', whyEn: 'Luke 1:46-55: "My soul magnifies the Lord..." Mary celebrates God\'s mercy toward the humble. The Magnificat is prayed daily at Vespers (Liturgy of the Hours) in the Church.' },
  { id: 'dq-051', question: 'Qual é a mensagem central da Carta de Tiago?', questionEn: 'What is the central message of the Letter of James?', options: ['A justificação pela sola fide', 'A fé sem obras é morta', 'A ressurreição dos mortos', 'O papel do Espírito Santo'], optionsEn: ['Justification by faith alone', 'Faith without works is dead', 'The resurrection of the dead', 'The role of the Holy Spirit'], correct: 1, why: 'Tiago 2,17: "Assim também a fé: se não tiver obras, é morta em si mesma". Tiago combate uma fé reduzida a palavras, sem obras de caridade. Paulo e Tiago se completam: Paulo nega que as obras da Lei justifiquem, e Tiago nega que uma fé sem obras salve.', whyEn: 'James 2:17: "So faith also, if it have not works, is dead in itself". James opposes a faith reduced to words, without works of charity. Paul and James complement each other: Paul denies that the works of the Law justify, and James denies that a faith without works saves.' },
  { id: 'dq-052', question: 'O que Jesus quis dizer com "Eu sou o caminho, a verdade e a vida" (Jo 14,6)?', questionEn: 'What did Jesus mean by "I am the way, the truth, and the life" (Jn 14:6)?', options: ['Que seguir uma regra moral leva a Deus', 'Que ele é o único mediador entre Deus e os homens, a única via de salvação', 'Que a fé cristã é superior às outras religiões culturalmente', 'Que a Bíblia é o único caminho para conhecer Deus'], optionsEn: ['That following a moral rule leads to God', 'That he is the sole mediator between God and men, the only way of salvation', 'That Christianity is culturally superior to other religions', 'That the Bible is the only way to know God'], correct: 1, why: 'Jesus afirma ser o único mediador (1 Tm 2,5) e a única porta (Jo 10,9). "Caminho" (acesso ao Pai), "verdade" (Ele mesmo é a verdade divina encarnada) e "vida" (oferece a vida divina). Contexto: consolar os apóstolos antes da Paixão.', whyEn: 'Jesus affirms himself as the sole mediator (1 Tm 2:5) and the only gate (Jn 10:9). "Way" (access to the Father), "truth" (He is the incarnate divine truth), and "life" (He offers divine life). Context: consoling the apostles before the Passion.' },
  { id: 'dq-053', question: 'Qual é a última palavra de Jesus na Cruz, segundo o Evangelho de João?', questionEn: 'What is the last word of Jesus on the Cross, according to the Gospel of John?', options: ['"Meu Deus, por que me abandonaste?"', '"Pai, nas tuas mãos entrego o meu espírito"', '"Tudo está consumado"', '"Tenho sede"'], optionsEn: ['"My God, why have you forsaken me?"', '"Father, into your hands I commit my spirit"', '"It is finished"', '"I thirst"'], correct: 2, why: 'João 19,30: "Havendo Jesus tomado do vinagre, disse: Tudo está consumado. Inclinou a cabeça e entregou o espírito". O grego tetélestai indica uma obra levada a termo. Mateus e Marcos registram o clamor do Salmo 22 (21), e Lucas o "Pai, nas tuas mãos entrego o meu espírito".', whyEn: 'John 19:30: "Jesus therefore, when he had taken the vinegar, said: It is consummated" (in other translations, "It is finished"). The Greek tetelestai indicates a work brought to completion. Matthew and Mark record the cry of Psalm 22, and Luke the "Father, into your hands I commit my spirit".' },
  { id: 'dq-054', question: 'O que é o "tempo comum" no calendário litúrgico?', questionEn: 'What is "Ordinary Time" in the liturgical calendar?', options: ['Os períodos sem importância no ano litúrgico', 'Os períodos do ano litúrgico que não estão em Advento, Natal, Quaresma ou Páscoa', 'O tempo após Pentecostes até o Advento apenas', 'Qualquer período em que a Missa pode ser celebrada de forma simplificada'], optionsEn: ['Unimportant periods in the liturgical year', 'Periods of the liturgical year not in Advent, Christmas, Lent, or Easter', 'The time from Pentecost to Advent only', 'Any period when Mass may be celebrated in simplified form'], correct: 1, why: 'O Tempo Comum (anteriormente "Tempo depois de Pentecostes/Epifania") é o período ordinário do crescimento cristão. A cor é verde (esperança). Representa ~33 semanas do ano, celebrando a totalidade do mistério de Cristo.', whyEn: 'Ordinary Time (formerly "Time after Pentecost/Epiphany") is the ordinary period of Christian growth. The color is green (hope). It represents ~33 weeks of the year, celebrating the totality of the mystery of Christ.' },
  { id: 'dq-055', question: 'Quem é Nossa Senhora de Guadalupe e por que é importante?', questionEn: 'Who is Our Lady of Guadalupe and why is she important?', options: ['Uma imagem medieval europeia levada para o México', 'Maria, que apareceu em 1531 ao indígena Juan Diego, deixando sua imagem na tilma; padroeira da América', 'Uma santa mexicana do séc. XVI', 'Uma aparição não reconhecida pela Igreja'], optionsEn: ['A medieval European image brought to Mexico', 'Mary, who appeared in 1531 to the indigenous Juan Diego, leaving her image on his tilma; patroness of the Americas', 'A Mexican saint of the 16th century', 'An apparition not recognized by the Church'], correct: 1, why: 'Segundo a tradição, em dezembro de 1531 Maria apareceu a São Juan Diego no monte Tepeyac, perto da Cidade do México, e sua imagem ficou na tilma dele, hoje venerada na Basílica de Guadalupe. Juan Diego foi canonizado em 2002. A devoção marcou a evangelização do México, e Nossa Senhora de Guadalupe é venerada como padroeira da América.', whyEn: 'According to tradition, in December 1531 Mary appeared to St. Juan Diego on Tepeyac hill, near Mexico City, and her image remained on his tilma, now venerated in the Basilica of Guadalupe. Juan Diego was canonized in 2002. The devotion shaped the evangelization of Mexico, and Our Lady of Guadalupe is venerated as patroness of the Americas.' },
  { id: 'dq-056', question: 'O que é a "Lectio Continua" na liturgia?', questionEn: 'What is "Lectio Continua" in the liturgy?', options: ['A leitura seguida e contínua de livros bíblicos ao longo do ano litúrgico', 'A repetição dos mesmos textos todos os domingos', 'A leitura em voz alta de toda a Bíblia em um único culto', 'O estudo bíblico em grupo'], optionsEn: ['The sequential reading of biblical books throughout the liturgical year', 'The repetition of the same texts every Sunday', 'The reading aloud of the entire Bible in a single service', 'Bible study in a group'], correct: 0, why: 'A lectio continua é ler os livros bíblicos em sequência ao longo dos dias, para que a comunidade conheça trechos mais amplos da Escritura. O lecionário atual segue esse critério em boa parte das leituras, com ciclo de três anos aos domingos e de dois anos nos dias de semana (Sacrosanctum Concilium 51).', whyEn: 'Lectio continua is reading the biblical books in sequence over successive days, so that the community comes to know broader portions of Scripture. The current lectionary follows this principle in many readings, with a three-year cycle on Sundays and a two-year cycle on weekdays (Sacrosanctum Concilium 51).' },
  { id: 'dq-057', question: 'Qual é o nome do documento que o Papa Bento XVI escreveu sobre o amor de Deus?', questionEn: 'What is the name of the document Pope Benedict XVI wrote about God\'s love?', options: ['Laudato Si', 'Deus Caritas Est', 'Evangelii Gaudium', 'Amoris Laetitia'], optionsEn: ['Laudato Si', 'Deus Caritas Est', 'Evangelii Gaudium', 'Amoris Laetitia'], correct: 1, why: '"Deus Caritas Est" (Deus é Amor, 2005) foi a primeira encíclica de Bento XVI. Explora o amor divino (ágape) e humano (eros) e a missão da caridade da Igreja. Baseada em 1 João 4,16: "Deus é amor".', whyEn: '"Deus Caritas Est" (God Is Love, 2005) was Benedict XVI\'s first encyclical. It explores divine love (agape) and human love (eros) and the Church\'s mission of charity. Based on 1 John 4:16: "God is love".' },
  { id: 'dq-058', question: 'O que é o "Exame de Consciência" como prática espiritual?', questionEn: 'What is the "Examination of Conscience" as a spiritual practice?', options: ['Uma lista de pecados para memorizar', 'Uma revisão diária da própria vida à luz de Deus, identificando graças e falhas', 'Uma avaliação psicológica da personalidade', 'O ato de confessar pecados ao padre'], optionsEn: ['A list of sins to memorize', 'A daily review of one\'s life in the light of God, identifying graces and failures', 'A psychological personality assessment', 'The act of confessing sins to a priest'], correct: 1, why: 'A prática é antiga, mas Santo Inácio de Loyola a organizou nos Exercícios Espirituais (aprovados em 1548) em cinco passos: agradecer, pedir luz, rever o dia, pedir perdão e propor emenda. Prepara para a Confissão e ajuda no crescimento espiritual.', whyEn: 'The practice is ancient, but St. Ignatius of Loyola organized it in the Spiritual Exercises (approved in 1548) in five steps: giving thanks, asking for light, reviewing the day, asking forgiveness and resolving to amend. It prepares for Confession and helps spiritual growth.' },
  { id: 'dq-059', question: 'Em qual monte Moisés recebeu os Dez Mandamentos?', questionEn: 'On which mountain did Moses receive the Ten Commandments?', options: ['Monte das Oliveiras', 'Monte Sião', 'Monte Sinai', 'Monte Carmelo'], optionsEn: ['Mount of Olives', 'Mount Zion', 'Mount Sinai', 'Mount Carmel'], correct: 2, why: 'Êxodo 19-20: Moisés recebeu a Lei no Monte Sinai (também chamado Horeb). A aliança sinaítica estabeleceu Israel como povo de Deus. Os 10 Mandamentos são a base da moral judaica e cristã.', whyEn: 'Exodus 19-20: Moses received the Law at Mount Sinai (also called Horeb). The Sinai covenant established Israel as God\'s people. The 10 Commandments are the basis of Jewish and Christian morality.' },
  { id: 'dq-060', question: 'Qual é a principal diferença entre Católicos e Protestantes na visão da justificação?', questionEn: 'What is the main difference between Catholics and Protestants in the view of justification?', options: ['Católicos negam que a fé seja necessária; protestantes a exigem', 'Protestantes ensinam justificação por fé somente (forense); Católicos ensinam justificação que realmente transforma (ontológica) pela fé e cooperação', 'Não há diferença significativa hoje', 'Católicos aceitam mais pecados como perdoáveis'], optionsEn: ['Catholics deny faith is necessary; Protestants require it', 'Protestants teach justification by faith alone (forensic); Catholics teach justification that truly transforms (ontological) through faith and cooperation', 'There is no significant difference today', 'Catholics accept more sins as forgivable'], correct: 1, why: 'Na tradição luterana, a justificação é sobretudo forense: Deus declara justo o pecador, imputando-lhe a justiça de Cristo. Trento (sessão VI, 1547) ensinou que ela não é só remissão dos pecados, mas santificação e renovação do homem interior. A Declaração Conjunta sobre a Doutrina da Justificação (1999), entre católicos e luteranos, chegou a um consenso em verdades básicas, mas diferenças permanecem.', whyEn: 'In the Lutheran tradition, justification is above all forensic: God declares the sinner righteous, imputing to him the righteousness of Christ. Trent (session VI, 1547) taught that it is not only the remission of sins but the sanctification and renewal of the inner man. The Joint Declaration on the Doctrine of Justification (1999), between Catholics and Lutherans, reached a consensus on basic truths, but differences remain.' },
  { id: 'dq-061', question: 'O que é o "advento" em sentido teológico?', questionEn: 'What is "advent" in the theological sense?', options: ['A chegada de um dignitário eclesiástico', 'A vinda ou chegada de Cristo: a primeira (Encarnação) e a segunda (parusia)', 'A preparação para uma missão', 'O início do ano eclesiástico apenas'], optionsEn: ['The arrival of an ecclesiastical dignitary', 'The coming or arrival of Christ: the first (Incarnation) and the second (parousia)', 'The preparation for a mission', 'The beginning of the ecclesiastical year only'], correct: 1, why: 'Adventus é a palavra latina que traduz o grego parousía (chegada, presença). O Advento celebra as duas vindas de Cristo: a primeira, na Encarnação, e a segunda, esperada no fim dos tempos. É tempo de espera ativa e conversão.', whyEn: 'Adventus is the Latin word that renders the Greek parousia (coming, presence). Advent celebrates Christ\'s two comings: the first, in the Incarnation, and the second, awaited at the end of time. It is a time of active waiting and conversion.' },
  { id: 'dq-062', question: 'Qual milagre é narrado em todos os quatro Evangelhos?', questionEn: 'Which miracle is narrated in all four Gospels?', options: ['A ressurreição de Lázaro', 'A cura de um cego', 'A multiplicação dos pães', 'Jesus caminhando sobre as águas'], optionsEn: ['The raising of Lazarus', 'The healing of a blind man', 'The multiplication of the loaves', 'Jesus walking on water'], correct: 2, why: 'A multiplicação dos pães e dos peixes aparece nos quatro Evangelhos (Mt 14; Mc 6; Lc 9; Jo 6). É o único milagre do ministério público de Jesus narrado pelos quatro, e João o liga ao discurso sobre o Pão da Vida.', whyEn: 'The multiplication of the loaves and fish appears in all four Gospels (Mt 14; Mk 6; Lk 9; Jn 6). It is the only miracle of Jesus\'s public ministry narrated by all four, and John links it to the Bread of Life discourse.' },
  { id: 'dq-063', question: 'Qual é o nome do anjo que anunciou o nascimento de Jesus a Maria?', questionEn: 'What is the name of the angel who announced the birth of Jesus to Mary?', options: ['Miguel', 'Rafael', 'Gabriel', 'Uriel'], optionsEn: ['Michael', 'Raphael', 'Gabriel', 'Uriel'], correct: 2, why: 'Gabriel (Lc 1,26) foi enviado a Nazaré para anunciar a Maria. Gabriel também interpretou as visões de Daniel (Dn 8-9) e anunciou a Zacarias o nascimento de João Batista (Lc 1,11-20).', whyEn: 'Gabriel (Lk 1:26) was sent to Nazareth to announce to Mary. Gabriel also interpreted Daniel\'s visions (Dn 8-9) and announced to Zechariah the birth of John the Baptist (Lk 1:11-20).' },
  { id: 'dq-064', question: 'Qual é a diferença entre "contemplação" e "meditação" na tradição espiritual cristã?', questionEn: 'What is the difference between "contemplation" and "meditation" in Christian spiritual tradition?', options: ['São sinônimos', 'Meditação é pensar reflexivamente sobre verdades religiosas; contemplação é presença amorosa e silenciosa a Deus além dos conceitos', 'Meditação é mais profunda que contemplação', 'Contemplação é apenas para religiosos e contemplativos'], optionsEn: ['They are synonyms', 'Meditation is reflective thinking about religious truths; contemplation is loving, silent presence to God beyond concepts', 'Meditation is deeper than contemplation', 'Contemplation is only for religious and contemplatives'], correct: 1, why: 'Na tradição mística (João da Cruz, Teresa de Ávila), a meditação usa a razão e a imaginação para encontrar Deus nas verdades reveladas. A contemplação é dom de Deus: presença silenciosa e amorosa, além dos raciocínios (Catecismo §2705-2724).', whyEn: 'In the mystical tradition (John of the Cross, Teresa of Ávila), meditation uses reason and imagination to find God in revealed truths. Contemplation is God\'s gift: a silent, loving presence beyond reasoning (Catechism §2705-2724).' },
  { id: 'dq-065', question: 'Qual é o papel de Nossa Senhora na Redenção, segundo a teologia católica?', questionEn: 'What is Our Lady\'s role in Redemption, according to Catholic theology?', options: ['Maria co-redimiu a humanidade igualmente a Jesus', 'Maria cooperou de modo único e subordinado na obra do Redentor, como Mãe e intercessora', 'Maria não tem papel teológico na Redenção', 'Maria é a quarta pessoa da Trindade'], optionsEn: ['Mary co-redeemed humanity equally with Jesus', 'Mary cooperated in a unique and subordinate way in the work of the Redeemer, as Mother and intercessor', 'Mary has no theological role in Redemption', 'Mary is the fourth person of the Trinity'], correct: 1, why: 'A Lumen Gentium (n. 61-62) ensina que Maria cooperou de modo singular na obra do Salvador e que sua função materna não diminui a mediação única de Cristo. Em 2025, a nota Mater Populi Fidelis, do Dicastério para a Doutrina da Fé, disse que é sempre inoportuno usar o título "corredentora", porque ele pode obscurecer que só Cristo é o Redentor.', whyEn: 'Lumen Gentium (no. 61-62) teaches that Mary cooperated in a singular way in the work of the Savior and that her maternal role does not diminish the unique mediation of Christ. In 2025 the note Mater Populi Fidelis, from the Dicastery for the Doctrine of the Faith, said it is "always inappropriate" to use the title "Co-redemptrix", because it can obscure that Christ alone is the Redeemer.' },
  { id: 'dq-066', question: 'O que celebra a Solenidade de Todos os Santos (1° de novembro)?', questionEn: 'What does the Solemnity of All Saints (November 1) celebrate?', options: ['Os mártires cristãos apenas', 'Todos os santos canonizados e os que estão no Céu, conhecidos ou desconhecidos', 'Os fiéis defuntos que estão no purgatório', 'Os anjos e arcanjos'], optionsEn: ['Christian martyrs only', 'All canonized saints and those in Heaven, known or unknown', 'The faithful departed who are in purgatory', 'Angels and archangels'], correct: 1, why: 'A festa de Todos os Santos honra a multidão incontável dos que estão no Céu (Ap 7,9), conhecidos ou não. No dia seguinte, 2 de novembro, a Comemoração de Todos os Fiéis Defuntos (Finados) é o dia de rezar pelos que estão no purgatório.', whyEn: 'The feast of All Saints honors the countless multitude of those in Heaven (Rev 7:9), known or unknown. The following day, November 2, the Commemoration of All the Faithful Departed (All Souls) is the day to pray for those in purgatory.' },
  { id: 'dq-067', question: 'Qual gesto professa ao mesmo tempo a fé na Trindade e na Redenção?', questionEn: 'Which gesture professes faith in both the Trinity and the Redemption?', options: ['O sinal da cruz', 'Ajoelhar-se', 'As mãos postas em oração', 'O beijo da paz'], optionsEn: ['The Sign of the Cross', 'Kneeling', 'Hands joined in prayer', 'The kiss of peace'], correct: 0, why: 'O sinal da cruz, feito "em nome do Pai, e do Filho, e do Espírito Santo", traça a cruz da Redenção enquanto professa a Trindade. É muito antigo: por volta de 211, Tertuliano conta que os cristãos marcavam a fronte com o sinal da cruz em todas as ações. Abre e encerra a Missa.', whyEn: 'The Sign of the Cross, made "in the name of the Father, and of the Son, and of the Holy Spirit", traces the cross of the Redemption while professing the Trinity. It is very old: around 211 Tertullian says Christians marked their foreheads with the sign of the cross in all their actions. It opens and closes the Mass.' },
  { id: 'dq-068', question: 'O que é a "kénosis" de Cristo?', questionEn: 'What is Christ\'s "kenosis"?', options: ['Sua transfiguração no Monte Tabor', 'O esvaziamento voluntário de privilégios divinos ao se tornar homem (Fl 2,7)', 'Sua morte na Cruz', 'Sua descida ao inferno'], optionsEn: ['His transfiguration on Mount Tabor', 'The voluntary emptying of divine privileges in becoming man (Phil 2:7)', 'His death on the Cross', 'His descent to hell'], correct: 1, why: 'Filipenses 2,7: Cristo "aniquilou-se a si mesmo, assumindo a condição de escravo". A kénosis (do grego, esvaziamento) não quer dizer que o Filho deixou de ser Deus, e sim que, por amor, assumiu a condição humana com seus limites.', whyEn: 'Philippians 2:7: Christ "emptied himself, taking the form of a servant". Kenosis (Greek for emptying) does not mean the Son ceased to be God, but that out of love he took on the human condition with its limits.' },
  { id: 'dq-069', question: 'Qual é a posição da Igreja Católica sobre a pena de morte?', questionEn: 'What is the Catholic Church\'s position on capital punishment?', options: ['É sempre moralmente justificada para crimes graves', 'É inadmissível, pois atenta contra a inviolabilidade e a dignidade da pessoa (Catecismo §2267, redação de 2018)', 'É um assunto puramente político, sem posição oficial da Igreja', 'É permitida em casos de guerras justas'], optionsEn: ['It is always morally justified for serious crimes', 'It is inadmissible, as it attacks the inviolability and dignity of the person (Catechism §2267, 2018 wording)', 'It is a purely political matter, with no official Church position', 'It is permitted in cases of just wars'], correct: 1, why: 'Em 2018, Francisco aprovou a nova redação do §2267 do Catecismo: "a pena de morte é inadmissível, porque atenta contra a inviolabilidade e dignidade da pessoa". O próprio texto lembra que antes ela foi considerada um meio aceitável, ainda que extremo, para a tutela do bem comum.', whyEn: 'In 2018 Francis approved the new wording of §2267 of the Catechism: "the death penalty is inadmissible because it is an attack on the inviolability and dignity of the person". The text itself recalls that it was once considered an acceptable, albeit extreme, means of safeguarding the common good.' },
  { id: 'dq-070', question: 'Qual trecho da Bíblia descreve Deus formando o homem do barro da terra?', questionEn: 'Which passage of the Bible describes God forming man from the earth?', options: ['Gênesis 1', 'Gênesis 2', 'Jó', 'Salmo 139'], optionsEn: ['Genesis 1', 'Genesis 2', 'Job', 'Psalm 139'], correct: 1, why: 'Gênesis 2,7: "O Senhor Deus formou, pois, o homem do barro da terra, e inspirou-lhe nas narinas o sopro da vida". Gênesis 1 descreve a criação pela palavra ("Deus disse..."), e Gênesis 2 usa a imagem mais próxima do oleiro.', whyEn: 'Genesis 2:7: "the Lord God formed man of the slime of the earth: and breathed into his face the breath of life". Genesis 1 describes creation by the word ("God said..."), and Genesis 2 uses the closer image of the potter.' },
  { id: 'dq-071', question: 'Qual é o objetivo final da vida cristã, segundo o Catecismo da Igreja Católica?', questionEn: 'What is the ultimate goal of Christian life, according to the Catechism of the Catholic Church?', options: ['Ser uma boa pessoa e ajudar os outros', 'A visão beatífica: ver a Deus face a face e participar da vida divina por toda a eternidade', 'Alcançar a paz interior e o equilíbrio', 'Praticar os sacramentos e cumprir as obrigações religiosas'], optionsEn: ['Being a good person and helping others', 'The beatific vision: seeing God face to face and sharing divine life for all eternity', 'Achieving inner peace and balance', 'Practicing the sacraments and fulfilling religious obligations'], correct: 1, why: 'O Catecismo começa assim: "Deus, infinitamente perfeito e bem-aventurado em Si mesmo, num desígnio de pura bondade, criou livremente o homem para o tornar participante da sua vida bem-aventurada" (§1). E a bem-aventurança "faz-nos participantes da natureza divina e da vida eterna" (§1721), o que inclui a visão de Deus (§1720).', whyEn: 'The Catechism begins: "God, infinitely perfect and blessed in himself, in a plan of sheer goodness freely created man to make him share in his own blessed life" (§1). And beatitude "makes us partakers of the divine nature and of eternal life" (§1721), which includes the vision of God (§1720).' },
  { id: 'dq-072', question: 'Quantas tentações sofreu Jesus no deserto e quais foram?', questionEn: 'How many temptations did Jesus face in the desert and what were they?', options: ['Duas: riqueza e poder', 'Três: transformar pedras em pão, atirar-se do templo e adorar o diabo em troca de todos os reinos', 'Quatro: as mesmas de Israel no deserto', 'Cinco: as listas variam entre Evangelhos'], optionsEn: ['Two: wealth and power', 'Three: turning stones to bread, throwing himself from the temple, and worshipping the devil in exchange for all kingdoms', 'Four: the same as Israel in the desert', 'Five: the lists vary among Gospels'], correct: 1, why: 'Mateus 4,1-11 e Lucas 4,1-13 narram três tentações: transformar pedras em pão, atirar-se do pináculo do templo e adorar o diabo em troca dos reinos do mundo. A tradição as associa às três concupiscências de 1 João 2,16, e Jesus responde a cada uma com a Escritura.', whyEn: 'Matthew 4:1-11 and Luke 4:1-13 recount three temptations: turning stones into bread, throwing himself down from the pinnacle of the temple and worshipping the devil in exchange for the kingdoms of the world. Tradition associates them with the three concupiscences of 1 John 2:16, and Jesus answers each with Scripture.' },
  { id: 'dq-073', question: 'O que é a "Comunhão dos Santos"?', questionEn: 'What is the "Communion of Saints"?', options: ['O grupo de pessoas canonizadas pela Igreja', 'A unidade espiritual de todos os fiéis, na terra, no purgatório e no céu, que partilham os bens espirituais', 'A distribuição da Eucaristia', 'Uma antiga heresia'], optionsEn: ['The group of people canonized by the Church', 'The spiritual unity of all the faithful, on earth, in purgatory and in heaven, who share spiritual goods', 'The distribution of the Eucharist', 'An ancient heresy'], correct: 1, why: 'O Credo Apostólico professa "a comunhão dos santos". O Catecismo (§946-959) explica que ela une os fiéis que peregrinam na terra, os que se purificam e os que já estão na glória, com partilha de bens espirituais e intercessão mútua.', whyEn: 'The Apostles\' Creed professes "the communion of saints". The Catechism (§946-959) explains that it unites the faithful who are pilgrims on earth, those being purified and those already in glory, with a sharing of spiritual goods and mutual intercession.' },
  { id: 'dq-074', question: 'Qual é o "novo mandamento" que Jesus deu na Última Ceia?', questionEn: 'What is the "new commandment" Jesus gave at the Last Supper?', options: ['Amar a Deus acima de tudo', 'Amar-vos uns aos outros como Eu vos amei', 'Batizai todas as nações', 'Guardar o domingo santificado'], optionsEn: ['Love God above all things', 'Love one another as I have loved you', 'Baptize all nations', 'Keep Sunday holy'], correct: 1, why: 'João 13,34: "Dou-vos um novo mandamento: Amai-vos uns aos outros. Como eu vos tenho amado, assim também vós deveis amar-vos uns aos outros". É "novo" não porque fosse inédito (Lv 19,18), mas pela nova medida: "como eu vos tenho amado".', whyEn: 'John 13:34: "A new commandment I give to you, that you love one another: just as I have loved you, you also are to love one another." It is "new" not because it was unprecedented (Lv 19:18), but because of the new standard: "as I have loved you".' },
  { id: 'dq-075', question: 'Destas aparições marianas reconhecidas pela Igreja, qual é a mais antiga?', questionEn: 'Of these Marian apparitions recognized by the Church, which is the oldest?', options: ['Fátima (1917)', 'Lourdes (1858)', 'Guadalupe (1531)', 'Rue du Bac, Paris (1830)'], optionsEn: ['Fatima (1917)', 'Lourdes (1858)', 'Guadalupe (1531)', 'Rue du Bac, Paris (1830)'], correct: 2, why: 'Guadalupe (1531) vem antes de Rue du Bac (1830, Medalha Milagrosa), Lourdes (1858) e Fátima (1917). Há tradições ainda mais antigas, como a de Nossa Senhora do Pilar, em Saragoça.', whyEn: 'Guadalupe (1531) comes before Rue du Bac (1830, Miraculous Medal), Lourdes (1858) and Fatima (1917). There are even older traditions, such as that of Our Lady of the Pillar, in Zaragoza.' },
  { id: 'dq-076', question: 'O que é a "parusia"?', questionEn: 'What is the "parousia"?', options: ['A festa de Pentecostes', 'A segunda vinda gloriosa de Cristo no fim dos tempos', 'A presença de Cristo na Eucaristia', 'A morte de um papa'], optionsEn: ['The feast of Pentecost', 'The glorious second coming of Christ at the end of time', 'The presence of Christ in the Eucharist', 'The death of a pope'], correct: 1, why: '"Parousia" (em grego: presença/chegada) refere-se à segunda vinda de Cristo (Mt 24,27-31). Será visível, gloriosa e definitiva, marcando o julgamento final, a ressurreição dos mortos e o estabelecimento do Reino eterno.', whyEn: '"Parousia" (in Greek: presence/coming) refers to Christ\'s second coming (Mt 24:27-31). It will be visible, glorious, and definitive, marking the final judgment, the resurrection of the dead, and the establishment of the eternal Kingdom.' },
  { id: 'dq-077', question: 'Qual é a mensagem de Fátima (1917) em síntese?', questionEn: 'What is the message of Fatima (1917) in summary?', options: ['Anunciar o fim do mundo iminente', 'Oração (especialmente o Rosário), penitência, conversão e consagração ao Imaculado Coração de Maria', 'Reformar a Igreja segundo visões apocalípticas', 'Revelar novos dogmas marianos'], optionsEn: ['Announce the imminent end of the world', 'Prayer (especially the Rosary), penance, conversion, and consecration to the Immaculate Heart of Mary', 'Reform the Church according to apocalyptic visions', 'Reveal new Marian dogmas'], correct: 1, why: 'Maria apareceu seis vezes a Lúcia, Francisco e Jacinta, de maio a outubro de 1917. Pediu o terço diário, oração, penitência e a consagração da Rússia ao seu Imaculado Coração. O segredo inclui a visão do inferno, o anúncio de outra guerra e a visão do "bispo vestido de branco", que a Santa Sé relacionou ao atentado de 1981. O bispo de Leiria reconheceu as aparições em 1930.', whyEn: 'Mary appeared six times to Lucia, Francisco and Jacinta, from May to October 1917. She asked for the daily Rosary, prayer, penance and the consecration of Russia to her Immaculate Heart. The secret includes the vision of hell, the announcement of another war and the vision of the "bishop dressed in white", which the Holy See related to the 1981 assassination attempt. The bishop of Leiria recognized the apparitions in 1930.' },
  { id: 'dq-078', question: 'O que Jesus disse a Nicodemos sobre o novo nascimento (Jo 3)?', questionEn: 'What did Jesus say to Nicodemus about being born again (Jn 3)?', options: ['Que só os judeus podem ser salvos', 'Que é preciso nascer de novo "de água e do Espírito" para entrar no Reino de Deus', 'Que basta crer sinceramente para ser salvo', 'Que a Torá é o único caminho'], optionsEn: ['That only Jews can be saved', 'That one must be born again "of water and the Spirit" to enter the Kingdom of God', 'That sincere belief alone is enough to be saved', 'That the Torah is the only way'], correct: 1, why: 'João 3,5: "quem não renascer da água e do Espírito não poderá entrar no Reino de Deus". A tradição católica vê aqui a necessidade do Batismo (Catecismo §1257). "Nascer de novo" indica uma transformação radical, não só uma nova mentalidade.', whyEn: 'John 3:5: "Unless one is born of water and the Spirit, he cannot enter the kingdom of God." Catholic tradition sees here the necessity of Baptism. "Born again" indicates radical transformation, not just a new mindset.' },
  { id: 'dq-079', question: 'Qual é o papel dos anjos na teologia católica?', questionEn: 'What is the role of angels in Catholic theology?', options: ['A fé nos anjos é opcional e periférica', 'São seres espirituais criados, mensageiros de Deus, adoradores e protetores dos humanos (anjos da guarda)', 'São antigas pessoas que morreram e foram elevadas', 'São símbolos poéticos das ações divinas'], optionsEn: ['Belief in angels is optional and peripheral', 'They are created spiritual beings, God\'s messengers, worshippers, and protectors of humans (guardian angels)', 'They are ancient people who died and were elevated', 'They are poetic symbols of divine actions'], correct: 1, why: 'O Catecismo (§328) diz que a existência dos anjos é verdade de fé. Eles são criaturas puramente espirituais que adoram a Deus, levam suas mensagens e protegem os homens (§329-336): "Cada fiel tem a seu lado um anjo como protetor e pastor para o guiar na vida" (§336, citando São Basílio).', whyEn: 'The Catechism (§328) says the existence of angels is a truth of faith. They are purely spiritual creatures who adore God, carry his messages and protect men (§329-336): "Beside each believer stands an angel as protector and shepherd leading him to life" (§336, quoting St. Basil).' },
  { id: 'dq-080', question: 'O que é o "Credo Niceno-Constantinopolitano"?', questionEn: 'What is the "Nicene-Constantinopolitan Creed"?', options: ['A versão curta do Credo rezada nas Missas dominicais', 'A profissão de fé elaborada nos Concílios de Niceia (325) e Constantinopla I (381) e recitada na Missa', 'Um documento medieval sobre os papas', 'Uma oração particular de São Nicéforo'], optionsEn: ['The short version of the Creed prayed at Sunday Mass', 'The profession of faith elaborated at the Councils of Nicaea (325) and Constantinople I (381) and recited at Mass', 'A medieval document about the popes', 'A private prayer by St. Nicephorus'], correct: 1, why: 'O Credo niceno-constantinopolitano é a profissão de fé comum a católicos, ortodoxos e muitas igrejas protestantes, recitada nas Missas de domingo. Niceia (325) afirmou a consubstancialidade do Filho, e Constantinopla (381) a divindade do Espírito Santo.', whyEn: 'The Nicene-Constantinopolitan Creed is the profession of faith shared by Catholics, Orthodox and many Protestant churches, recited at Sunday Masses. Nicaea (325) affirmed the consubstantiality of the Son, and Constantinople (381) the divinity of the Holy Spirit.' },
  { id: 'dq-081', question: 'Qual é a principal diferença entre a Páscoa judaica e a Páscoa cristã?', questionEn: 'What is the main difference between the Jewish Passover and the Christian Easter?', options: ['Não há diferença: são a mesma festa', 'A Páscoa judaica celebra a libertação do Egito; a cristã celebra a Ressurreição de Cristo, cumprimento e superação da primeira', 'A Páscoa cristã é anterior à judaica', 'A Páscoa judaica não tem caráter religioso'], optionsEn: ['There is no difference: they are the same feast', 'The Jewish Passover celebrates liberation from Egypt; the Christian celebrates the Resurrection of Christ, fulfillment and surpassing of the first', 'The Christian Easter predates the Jewish Passover', 'The Jewish Passover has no religious character'], correct: 1, why: 'A Páscoa judaica (Pessach) celebra a saída do Egito. Jesus morreu na Páscoa judaica, tornando-se o "Cordeiro de Deus" (1 Cor 5,7: "Cristo, nossa Páscoa, foi imolado"). A Ressurreição é a nova e definitiva passagem da morte para a vida.', whyEn: 'The Jewish Passover (Pesach) celebrates the Exodus from Egypt. Jesus died at Passover, becoming the "Lamb of God" (1 Cor 5:7: "Christ, our Passover lamb, has been sacrificed"). The Resurrection is the new and definitive passage from death to life.' },
  { id: 'dq-082', question: 'O que é o jejum eucarístico?', questionEn: 'What is the Eucharistic fast?', options: ['Abster-se da Eucaristia por 40 dias', 'Abster-se de alimentos e bebidas (exceto água e medicamentos) por uma hora antes da Comunhão', 'Não comer carne às sextas-feiras', 'Jejuar por 24 horas antes da confissão'], optionsEn: ['Abstaining from the Eucharist for 40 days', 'Abstaining from food and drink (except water and medicine) for one hour before Communion', 'Not eating meat on Fridays', 'Fasting for 24 hours before confession'], correct: 1, why: 'O Código de Direito Canônico (cân. 919) pede abstinência de alimentos e bebidas, exceto água e remédios, por pelo menos uma hora antes da Comunhão, regra fixada por Paulo VI em 1964. Antes, o jejum ia desde a meia-noite, e Pio XII o reduziu para três horas em 1957.', whyEn: 'The Code of Canon Law (can. 919) asks for abstinence from food and drink, except water and medicine, for at least one hour before Communion, a rule set by Paul VI in 1964. Before that the fast ran from midnight, and Pius XII reduced it to three hours in 1957.' },
  { id: 'dq-083', question: 'Qual é o sentido teológico do "sábado" no Antigo Testamento?', questionEn: 'What is the theological meaning of the "Sabbath" in the Old Testament?', options: ['Um dia de trabalho leve', 'O dia do descanso consagrado a Deus, em memória da criação e da aliança com Israel', 'Apenas uma norma higiênica', 'O dia de sacrifícios no templo'], optionsEn: ['A day of light work', 'The day of rest consecrated to God, in memory of creation and the covenant with Israel', 'Merely a hygienic norm', 'The day of temple sacrifices'], correct: 1, why: 'Gênesis 2,2-3 e Êxodo 20,8-11 apresentam o sábado como sétimo dia, separado e consagrado, em memória da criação, e Êxodo 31,16-17 o chama de sinal da aliança com Israel. Para os cristãos, o domingo, dia da Ressurreição, cumpre o sentido do sábado (Catecismo §2175).', whyEn: 'Genesis 2:2-3 and Exodus 20:8-11 present the Sabbath as the seventh day, set apart and consecrated, in memory of creation, and Exodus 31:16-17 calls it a sign of the covenant with Israel. For Christians, Sunday, the day of the Resurrection, fulfills the meaning of the Sabbath (Catechism §2175).' },
  { id: 'dq-084', question: 'O que é a "Traditio Apostolica" de Hipólito de Roma?', questionEn: 'What is the "Traditio Apostolica" of Hippolytus of Rome?', options: ['Um documento sobre a sucessão papal', 'Uma antiga ordem eclesiástica, com textos de ordenação, da Eucaristia e do Batismo', 'Um tratado sobre heresias gnósticas', 'A primeira lista do cânon bíblico'], optionsEn: ['A document about papal succession', 'An ancient church order, with texts for ordination, the Eucharist and Baptism', 'A treatise on Gnostic heresies', 'The first list of the biblical canon'], correct: 1, why: 'A Tradição Apostólica é tradicionalmente atribuída a Hipólito de Roma (por volta de 215), mas muitos estudiosos hoje a veem como compilação com camadas dos séculos II a IV. Traz uma das orações eucarísticas mais antigas que se conhecem, base da Oração Eucarística II do Missal de Paulo VI.', whyEn: 'The Apostolic Tradition is traditionally attributed to Hippolytus of Rome (around 215), but many scholars today see it as a compilation with layers from the 2nd to the 4th centuries. It contains one of the oldest known eucharistic prayers, the basis of Eucharistic Prayer II of the Missal of Paul VI.' },
  { id: 'dq-085', question: 'Qual é o pecado original em sua essência teológica?', questionEn: 'What is original sin in its theological essence?', options: ['Um pecado sexual cometido por Adão e Eva', 'A desobediência que rompeu a relação de Adão com Deus e transmitiu a toda a humanidade uma natureza ferida, privada da santidade e justiça originais', 'Um mito pedagógico sem realidade histórica', 'A inclinação ao mal apenas'], optionsEn: ['A sexual sin committed by Adam and Eve', 'The disobedience that broke Adam\'s relationship with God and passed on to all humanity a wounded nature, deprived of original holiness and justice', 'A pedagogical myth without historical reality', 'Only the inclination toward evil'], correct: 1, why: 'O pecado original (Gn 3; Rm 5,12-19) não é um pecado sexual. É a desobediência que fez Adão perder a santidade e a justiça originais e transmitiu ao gênero humano uma natureza ferida (Catecismo §416-417). O Batismo apaga o pecado original, mas permanecem suas consequências, como a concupiscência e a morte (§405).', whyEn: 'Original sin (Gn 3; Rom 5:12-19) is not a sexual sin. It is the disobedience by which Adam lost original holiness and justice and passed on to the human race a wounded nature (Catechism §416-417). Baptism erases original sin, but its consequences remain, such as concupiscence and death (§405).' },
  { id: 'dq-086', question: 'Qual é a definição de "heresia" na teologia católica?', questionEn: 'What is the definition of "heresy" in Catholic theology?', options: ['Qualquer erro intelectual ou moral', 'A negação pertinaz, após o Batismo, de uma verdade que deve ser crida com fé divina e católica', 'A separação da autoridade eclesiástica sem negar doutrinas', 'A prática de magia ou ocultismo'], optionsEn: ['Any intellectual or moral error', 'The pertinacious denial, after Baptism, of a truth that must be believed with divine and catholic faith', 'Separation from ecclesiastical authority without denying doctrines', 'The practice of magic or occultism'], correct: 1, why: 'O Código de Direito Canônico (cân. 751) define heresia como a negação pertinaz, depois do Batismo, de uma verdade que deve ser crida com fé divina e católica. Apostasia é o repúdio total da fé, e cisma é a recusa de submissão ao Papa ou da comunhão com os membros da Igreja. A heresia exige pertinácia, não um simples erro de boa-fé.', whyEn: 'The Code of Canon Law (can. 751) defines heresy as the obstinate denial, after Baptism, of a truth that must be believed with divine and catholic faith. Apostasy is the total repudiation of the faith, and schism is the refusal of submission to the Pope or of communion with the members of the Church. Heresy requires obstinacy, not mere good-faith error.' },
  { id: 'dq-087', question: 'Qual é a posição da Igreja sobre a meditação budista (mindfulness)?', questionEn: 'What is the Church\'s position on Buddhist meditation (mindfulness)?', options: ['É proibida aos católicos', 'Técnicas de relaxamento e atenção plena podem ser usadas, mas devem ser integradas à oração cristã, evitando ideologias incompatíveis', 'É equivalente à lectio divina', 'A Igreja não tem posição sobre isso'], optionsEn: ['It is forbidden to Catholics', 'Relaxation and mindfulness techniques may be used, but must be integrated into Christian prayer, avoiding incompatible ideologies', 'It is equivalent to lectio divina', 'The Church has no position on this'], correct: 1, why: 'A carta Orationis formas (1989), da Congregação para a Doutrina da Fé, admite aproveitar elementos de métodos orientais desde que não substituam a oração cristã, e o documento Jesus Cristo, portador da água viva (2003), sobre a Nova Era, alerta contra práticas ligadas a visões de mundo incompatíveis com a fé, como o panteísmo e a fusão com o cosmos.', whyEn: 'The letter Orationis formas (1989), from the Congregation for the Doctrine of the Faith, allows elements of Eastern methods to be used as long as they do not replace Christian prayer, and the document Jesus Christ, the Bearer of the Water of Life (2003), on the New Age, warns against practices tied to worldviews incompatible with the faith, such as pantheism and fusion with the cosmos.' },
  { id: 'dq-088', question: 'O que é o "exame de consciência" antes da Confissão?', questionEn: 'What is the "examination of conscience" before Confession?', options: ['Uma lista de pecados pré-impressa', 'Uma reflexão pessoal sobre os pecados cometidos desde a última confissão, à luz da lei de Deus e da Igreja', 'A absolvição geral dada antes do rito individual', 'Uma oração de ação de graças'], optionsEn: ['A pre-printed list of sins', 'A personal reflection on sins committed since the last confession, in light of God\'s and the Church\'s law', 'The general absolution given before individual rite', 'A prayer of thanksgiving'], correct: 1, why: 'O exame de consciência prepara a confissão: identificar pecados, sua gravidade e número aproximado. Baseia-se nos mandamentos, nas obras de misericórdia e nas circunstâncias de estado de vida. Objetivo: contrição sincera e confissão íntegra.', whyEn: 'The examination of conscience prepares confession: identifying sins, their gravity, and approximate number. It is based on the commandments, the works of mercy, and the circumstances of one\'s state of life. Goal: sincere contrition and integral confession.' },
  { id: 'dq-089', question: 'O que distingue a fé teologal de uma simples crença ou opinião humana?', questionEn: 'What distinguishes theological faith from a mere human belief or opinion?', options: ['São sinônimos sem distinção', 'Fé (fides) é uma virtude teologal infusa por Deus; crença pode ser apenas opinião humana sem fundamento sobrenatural', 'Fé é mais fraca que crença', 'Crença refere-se às práticas; fé às doutrinas'], optionsEn: ['They are synonyms with no distinction', 'Faith (fides) is a theological virtue infused by God; belief can be merely human opinion without supernatural foundation', 'Faith is weaker than belief', 'Belief refers to practices; faith to doctrines'], correct: 1, why: 'A fé teologal é dom de Deus (Ef 2,8) que permite aderir com certeza às verdades reveladas. O Catecismo (§153) diz: "A fé é um dom de Deus, uma virtude sobrenatural infundida por Ele".', whyEn: 'Theological faith is a gift of God (Eph 2:8) that allows one to adhere with certainty to revealed truths. The Catechism (§153) says: "Faith is a gift of God, a supernatural virtue infused by him".' },
  { id: 'dq-090', question: 'O que é a "Sagrada Família" como modelo para as famílias cristãs?', questionEn: 'What is the "Holy Family" as a model for Christian families?', options: ['Um ideal inatingível e abstrato', 'Jesus, Maria e José como modelo de amor, obediência, trabalho e vida centrada em Deus para todas as famílias', 'Um símbolo medieval sem relevância atual', 'Apenas Maria e Jesus, sem José'], optionsEn: ['An unattainable and abstract ideal', 'Jesus, Mary, and Joseph as a model of love, obedience, work, and God-centered life for all families', 'A medieval symbol without contemporary relevance', 'Only Mary and Jesus, without Joseph'], correct: 1, why: 'A festa da Sagrada Família (domingo após o Natal) celebra Jesus, Maria e José em Nazaré. João Paulo II em "Familiaris Consortio" (1981) propôs a Sagrada Família como modelo: amor, respeito, trabalho, oração e obediência a Deus.', whyEn: 'The feast of the Holy Family (Sunday after Christmas) celebrates Jesus, Mary, and Joseph in Nazareth. John Paul II in "Familiaris Consortio" (1981) proposed the Holy Family as a model: love, respect, work, prayer, and obedience to God.' },
  { id: 'dq-091', question: 'Qual é o principal argumento filosófico a favor da existência de uma lei moral objetiva?', questionEn: 'What is the main philosophical argument in favor of the existence of an objective moral law?', options: ['A maioria das pessoas concorda com certos valores básicos', 'A consciência moral universal indica que há uma lei inscrita na razão humana (lei natural), apontando para um Legislador', 'As leis civis refletem a moral objetiva', 'Cada cultura tem seus próprios valores igualmente válidos'], optionsEn: ['Most people agree on certain basic values', 'Universal moral conscience indicates there is a law inscribed in human reason (natural law), pointing to a Lawgiver', 'Civil laws reflect objective morality', 'Each culture has equally valid values'], correct: 1, why: 'C. S. Lewis, em Cristianismo Puro e Simples (1952), e São Paulo, em Romanos 2,14-15 (a lei escrita no coração dos gentios), partem da consciência moral comum a todos os povos. O argumento sustenta que ela se explica melhor por uma lei inscrita na razão e por um Legislador do que como simples produto da evolução ou da cultura.', whyEn: 'C. S. Lewis, in Mere Christianity (1952), and St. Paul, in Romans 2:14-15 (the law written in the hearts of the Gentiles), start from the moral conscience shared by all peoples. The argument holds that it is better explained by a law inscribed in reason and by a Lawgiver than as a mere product of evolution or culture.' },
  { id: 'dq-092', question: 'O que Jesus diz sobre o divórcio no Evangelho?', questionEn: 'What does Jesus say about divorce in the Gospel?', options: ['É permitido em casos de adultério e abandono', '"O que Deus uniu, o homem não separe": o matrimônio válido é indissolúvel', 'O Antigo Testamento permite o divórcio e o Novo não muda isso', 'É assunto da lei civil, não da religião'], optionsEn: ['It is permitted in cases of adultery and abandonment', '"What God has joined together, let no man put asunder": a valid marriage is indissoluble', 'The Old Testament permits divorce and the New does not change this', 'It is a civil law matter, not religion'], correct: 1, why: 'Em Mateus 19,6-9 e Marcos 10,9, Jesus revoga a permissão de Moisés (Dt 24,1-4) e volta ao desígnio da criação (Gn 2,24). A exceção de Mateus ("salvo em caso de porneia") é lida pela Igreja como referência a uniões ilegítimas desde o início ou como permissão de separação, nunca de novo casamento (Catecismo §1614-1615 e §2382).', whyEn: 'In Matthew 19:6-9 and Mark 10:9, Jesus revokes the permission of Moses (Dt 24:1-4) and returns to the plan of creation (Gn 2:24). Matthew\'s exception ("except for porneia") is read by the Church as referring to unions that were illegitimate from the start or as permitting separation, never remarriage (Catechism §1614-1615 and §2382).' },
  { id: 'dq-093', question: 'Que apóstolo Paulo chama de "coluna" da Igreja, junto com Tiago e Pedro?', questionEn: 'Which apostle does Paul call a "pillar" of the Church, together with James and Peter?', options: ['Barnabé', 'João', 'André', 'Filipe'], optionsEn: ['Barnabas', 'John', 'Andrew', 'Philip'], correct: 1, why: 'Gálatas 2,9: "Tiago, Cefas e João, que são considerados as colunas". João, filho de Zebedeu, foi um dos três discípulos mais próximos de Jesus, com Pedro e Tiago de Zebedeu. O Tiago de Gálatas 2,9, porém, é outro: o "irmão do Senhor", líder da Igreja de Jerusalém, já que Tiago de Zebedeu fora morto por volta do ano 44 (At 12,2).', whyEn: 'Galatians 2:9: "James and Cephas and John, who seemed to be pillars". John, son of Zebedee, was one of the three disciples closest to Jesus, with Peter and James son of Zebedee. The James of Galatians 2:9, however, is another: the "brother of the Lord", leader of the Church in Jerusalem, since James son of Zebedee had been killed around the year 44 (Acts 12:2).' },
  { id: 'dq-094', question: 'O que é a "Nova Aliança" anunciada por Jeremias?', questionEn: 'What is the "New Covenant" announced by Jeremiah?', options: ['Uma aliança política entre Israel e Babilônia', 'Uma aliança em que Deus escreverá sua Lei no coração dos homens, não em pedra', 'Uma renovação da aliança mosaica com novas leis', 'A aliança que o Messias faria com os gentios apenas'], optionsEn: ['A political alliance between Israel and Babylon', 'A covenant in which God will write his Law on men\'s hearts, not on stone', 'A renewal of the Mosaic covenant with new laws', 'The covenant the Messiah would make with Gentiles only'], correct: 1, why: 'Jeremias 31,31-34: "Eis a aliança que, então, farei com a casa de Israel: Eu lhe incutirei a minha Lei; eu a gravarei em seu coração". Na Última Ceia, Jesus disse: "Este cálice é a Nova Aliança em meu sangue" (Lc 22,20).', whyEn: 'Jeremiah 31:31-34: "this shall be the covenant that I will make with the house of Israel: I will give my law in their bowels, and I will write it in their heart". At the Last Supper Jesus said: "This is the chalice, the new testament in my blood" (Lk 22:20).' },
  { id: 'dq-095', question: 'Qual é o significado do peixe (ICHTHYS) como símbolo cristão primitivo?', questionEn: 'What is the meaning of the fish (ICHTHYS) as an early Christian symbol?', options: ['Simbolizava que os primeiros cristãos eram pescadores', 'Era acrônimo grego de "Jesus Cristo, Filho de Deus, Salvador"', 'Era um sinal secreto para reuniões ilegais apenas', 'Representava a multiplicação dos pães e peixes'], optionsEn: ['It symbolized that early Christians were fishermen', 'It was a Greek acronym for "Jesus Christ, Son of God, Savior"', 'It was only a secret sign for illegal gatherings', 'It represented the multiplication of loaves and fish'], correct: 1, why: 'Ichthýs, "peixe" em grego, forma o acróstico Iesoûs Christós Theoû Hyiós Sotér: Jesus Cristo, Filho de Deus, Salvador. Tertuliano (por volta de 200) e a inscrição de Abércio (fim do séc. II) já usam a imagem, que identificava os cristãos antes de a cruz se tornar o símbolo predominante.', whyEn: 'Ichthys, "fish" in Greek, forms the acrostic Iesous Christos Theou Yios Soter: Jesus Christ, Son of God, Savior. Tertullian (around 200) and the inscription of Abercius (late 2nd century) already use the image, which identified Christians before the cross became the predominant symbol.' },
  { id: 'dq-096', question: 'Qual é a diferença entre "latria" e "dulia"?', questionEn: 'What is the difference between "latria" and "dulia"?', options: ['São sinônimos em latim eclesiástico', 'Latria é adoração devida só a Deus; dulia é veneração dos santos; hiperdulia é veneração especial a Maria', 'Latria é oração pública; dulia é oração privada', 'Latria é para os sacramentos; dulia para as devoções'], optionsEn: ['They are synonyms in ecclesiastical Latin', 'Latria is worship due to God alone; dulia is veneration of saints; hyperdulia is special veneration of Mary', 'Latria is public prayer; dulia is private prayer', 'Latria is for sacraments; dulia for devotions'], correct: 1, why: 'Tomás de Aquino explica que a latria (adoração) é devida só a Deus, a dulia (veneração) aos santos e a hiperdulia, grau mais alto da dulia, a Maria (Suma Teológica II-II, q. 103, a. 3-4; III, q. 25, a. 5). A distinção responde à acusação de idolatria: católicos não adoram santos.', whyEn: 'Thomas Aquinas explains that latria (adoration) is due to God alone, dulia (veneration) to the saints and hyperdulia, the highest degree of dulia, to Mary (Summa Theologiae II-II, q. 103, a. 3-4; III, q. 25, a. 5). The distinction answers the charge of idolatry: Catholics do not worship saints.' },
  { id: 'dq-097', question: 'Qual é o significado bíblico do nome "Emanuel"?', questionEn: 'What is the biblical meaning of the name "Emmanuel"?', options: ['Deus cura', 'Deus salva', 'Deus conosco', 'Deus forte'], optionsEn: ['God heals', 'God saves', 'God with us', 'God the Mighty'], correct: 2, why: '"Emanuel" vem do hebraico "Im-manu-El" (com-nós-Deus). Isaías 7,14 profetizou que um filho chamado Emanuel nasceria de uma virgem. Mateus 1,23 aplica isso a Jesus: "Deus conosco" é o tema central da Encarnação.', whyEn: '"Emmanuel" comes from the Hebrew "Im-manu-El" (with-us-God). Isaiah 7:14 prophesied that a son named Emmanuel would be born of a virgin. Matthew 1:23 applies this to Jesus: "God with us" is the central theme of the Incarnation.' },
  { id: 'dq-098', question: 'Qual é a principal distinção entre o catolicismo e a Ortodoxia no que se refere ao papado?', questionEn: 'What is the main distinction between Catholicism and Orthodoxy regarding the papacy?', options: ['A Ortodoxia aceita o papa como chefe supremo', 'A Ortodoxia reconhece ao Bispo de Roma uma primazia de honra, mas não jurisdição universal; o catolicismo ensina primazia de jurisdição', 'As duas Igrejas têm o mesmo ensinamento sobre o papa', 'A Ortodoxia tem um papa próprio em Constantinopla'], optionsEn: ['Orthodoxy accepts the pope as supreme head', 'Orthodoxy recognizes the Bishop of Rome a primacy of honor, but not universal jurisdiction; Catholicism teaches a primacy of jurisdiction', 'The two Churches have the same teaching about the pope', 'Orthodoxy has its own pope in Constantinople'], correct: 1, why: 'O primado romano esteve entre as causas do Cisma de 1054. Os ortodoxos reconhecem que o bispo de Roma teve, no primeiro milênio, um primado de honra (primus inter pares), mas não uma jurisdição universal sobre todas as Igrejas. O Concílio de Florença (1439) proclamou a união, que não se manteve no Oriente.', whyEn: 'Roman primacy was among the causes of the Schism of 1054. The Orthodox recognize that the bishop of Rome had, in the first millennium, a primacy of honor (primus inter pares), but not universal jurisdiction over all the Churches. The Council of Florence (1439) proclaimed union, which did not hold in the East.' },
  { id: 'dq-099', question: 'Qual dos quatro grandes Doutores da Igreja latina escreveu A Cidade de Deus?', questionEn: 'Which of the four great Doctors of the Latin Church wrote The City of God?', options: ['São Jerônimo', 'São Ambrósio', 'Santo Agostinho', 'São Gregório Magno'], optionsEn: ['St. Jerome', 'St. Ambrose', 'St. Augustine', 'St. Gregory the Great'], correct: 2, why: 'Agostinho de Hipona (354-430) escreveu A Cidade de Deus entre 413 e 426, além das Confissões e de A Trindade. Com Ambrósio, Jerônimo e Gregório Magno, forma o grupo dos quatro grandes Doutores latinos, assim reconhecidos por Bonifácio VIII em 1298. Sua obra marcou toda a teologia ocidental, e Lutero, Calvino e Jansênio o leram de modos diferentes.', whyEn: 'Augustine of Hippo (354-430) wrote The City of God between 413 and 426, as well as the Confessions and On the Trinity. With Ambrose, Jerome and Gregory the Great, he forms the group of the four great Latin Doctors, so recognized by Boniface VIII in 1298. His work shaped all of Western theology, and Luther, Calvin and Jansenius read him in different ways.' },
  { id: 'dq-100', question: 'O que significa "estar em estado de graça"?', questionEn: 'What does it mean to "be in a state of grace"?', options: ['Sentir paz interior e tranquilidade', 'Não ter pecados mortais na alma, estar em amizade com Deus por meio da graça santificante', 'Ter recebido todos os sacramentos da iniciação', 'Não ter cometido nenhum pecado venial recentemente'], optionsEn: ['Feeling inner peace and tranquility', 'Having no mortal sins on the soul, being in friendship with God through sanctifying grace', 'Having received all the sacraments of initiation', 'Not having committed any venial sins recently'], correct: 1, why: '"Estado de graça" significa ausência de pecado mortal e presença da graça santificante. É a condição para receber a Eucaristia dignamente (1 Cor 11,27-29) e para morrer em paz. O pecado mortal rompe esse estado; a Confissão o restaura.', whyEn: '"State of grace" means the absence of mortal sin and the presence of sanctifying grace. It is the condition for receiving the Eucharist worthily (1 Cor 11:27-29) and for dying in peace. Mortal sin breaks this state; Confession restores it.' },
];

// Escolhe quiz determinístico por dia (mesmo quiz pra todo mundo no mesmo dia).
// Semente 13 (e não a 7 padrão) para não cair no mesmo índice do versículo do dia.
export function getQuizOfDay(date = new Date()) {
  return DAILY_QUESTIONS[dailyIndex(DAILY_QUESTIONS.length, date, 13)];
}

// Escolhe N perguntas aleatórias (modo "praticar") sem repetir.
export function getRandomQuestions(n = 10) {
  const shuffled = [...QUIZ].sort(() => Math.random() - 0.5);
  return shuffled.slice(0, Math.min(n, QUIZ.length));
}

// Modo verdadeiro/falso: retorna N afirmações aleatórias.
export function getRandomTrueFalse(n = 10) {
  const shuffled = [...TRUE_FALSE].sort(() => Math.random() - 0.5);
  return shuffled.slice(0, Math.min(n, TRUE_FALSE.length));
}
